programs.sol:
"""A sparse recognizer of software references and markup.

Detect stack-frame 'at', document extensions, link-closing punctuation,
Git markers, and branch/version segments of URLs. Also recognize repeated
middle-dot leaders. Most other text gets zero. Some filename separators
and the repository hostname prefix get negative values. Coefficients are
approximate training means, not a complete description of this component.
Remember only the last 512 decoded characters, resetting per document.
"""
import re

READS = ()


def predict(token, before):
    word = token.strip()
    if token and len(token) >= 2 and set(token) == {'·'}:
        return 3.1 if '··' in before or not before else 0.0

    # Stack frames and Python's printed function locations, not prose 'at'.
    if word == 'at':
        line = re.split(r'\n|\\n', before)[-1]
        if token != 'at' or not line.strip():
            if ('<function ' in line or re.search(r'\.[a-z]{2,4}$', line)
                    or line.endswith(')') and '/' in line
                    or not line.strip() and (line or token.startswith('\t'))
                    or re.search(r'(ERR!|ERROR)\s*$', line)):
                return 4.9
        return 0.5 if not before else 0.0

    # Document filenames; README is particularly strong.
    if token == '.md':
        if before.endswith('README'):
            return 3.2
        return 2.0 if re.search(r'[A-Z_]{3,}$', before) else 2.8
    if token in ('.html', '.php', '.rs'):
        return {'.html': 1.4, '.php': 0.7, '.rs': 0.2}[token]
    if token == ' (' and re.search(r'\.[a-zA-Z]{2,5}$', before):
        return -1.6
    if token in ('\n', '\n\n') and re.search(r'\.[a-z]{2,5}$', before):
        return -0.1
    if word == 'filename':
        return 4.0 if before.endswith('<') else 1.0

    # Link targets: distinguish single, doubled, and citation-style closers.
    if token.startswith((')', '/)')):
        match = re.search(r'(?:\]\(|\burl\()([^\s()]*)$', before)
        target = match[1] if match else ''
        if not target and not re.search(r'\s', before):
            if re.search(r'://|\.md#|[\w-]+\.[a-z]{2,}/', before):
                target = before
        if target and '\\' not in target and '$' not in target:
            if token.startswith('))'):
                return 0.0
            if token == '){':
                return 2.6
            if not any(ch in target for ch in '/.#'):
                return 0.2
            if token == ')':
                return 6.4
            if token == '/)':
                return 5.6
            if re.search(r'\.(png|jpe?g|gif|svg)$', target, re.I):
                return 4.8
            return 1.9

    # Git output and shell commands.
    if token == 'index' and before.endswith('\n') and 'diff --git ' in before:
        return 4.1
    if word == 'HEAD' and re.search(r'\bgit\b[^\n]*$', before):
        return 3.6
    if word == 'head' and before.rstrip().endswith('|'):
        return 0.8
    if word == 'status' and before.endswith('git'):
        return 1.3
    if word in ('main', 'master'):
        if before.endswith('package'):
            return 3.9
        if before.endswith(('fn', 'func')):
            return 2.5
        if before.endswith(('int', 'void', 'def')):
            return 0.2
        if re.search(r'branch\s+[\x27\x22`]?$', before):
            return 4.5
        if before.endswith('  '):
            return 2.5

    # Repository paths and versioned documentation links.
    if token == 'repo' and before.endswith('://'):
        return -4.6
    if token == '/master':
        return 6.8 if before.endswith('/commits') else 16.2
    paths = {'/main': 1.7, '/workspace': -0.5, '/src': 0.2,
             '/index': 0.7, '/dev': 1.5, '/html': 1.0}
    if token in paths:
        return paths[token]
    if '://' in before:
        if token in ('/blob', '/tree'):
            return 4.7 if token == '/blob' else 3.2
        if token == '/latest':
            return 9.2 if before.endswith('/en') else 3.4
        if token == '/en':
            return 3.1
        if token == '/st' and before.endswith('/en'):
            return 5.3
    if token == 'able' and before.endswith('/en/st'):
        return 10.2
    if word == 'center' and re.search(r'(?:align\s*=\s*[\x22\x27]|\\begin\{)$', before):
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-512:]), predict(token, before)

"""A small syntax detector: assignment, standard output, and markup links.

Scores favor standalone variable names and declarations over members or calls;
mathematical context lowers them. Other rules recognize standard output APIs,
GitHub URLs, markup attributes and anchors, and line-initial list numbering.
Output keywords count even on commented-out or source-numbered lines.
Unrecognized syntax is assigned zero; this is not a complete activation model.
"""
import re

READS = ()

DECLARATION = re.compile(
    r'\b(var|let|const|int|String|double|float|auto|bool|final|local)\b')
PYTHON = re.compile(
    r'(?m)^\s*(\d+\s+)?(from\s+\w+\s+import|import\s+\w+|'
    r'def\s+\w+|for\s+\w+\s+in\b|if\b[^\n]+:|else:|with\b[^\n]+:)'
    r'|\bself\.')
MATH = re.compile(
    r'\\(frac|sum|sqrt|alpha|beta|theta|pi|mu|int|displaystyle)|'
    r'\b(thus|therefore|equation|Hence|Similarly|Alternatively|Let|Suppose)\b')
ATTRIBUTES = {'class', 'id', 'name', 'href', 'src', 'rel', 'target',
              'type', 'width', 'height', 'value', 'align', 'cref'}


def statement(line):
    # Source listings and diffs may put a line number or +/- before the code.
    return re.sub(r'^\s*(?:\d+\s+)?(?:[+-]\s+)?', '', line).strip()


def assignment(token, text, line):
    """Estimate the strength of a variable-binding delimiter."""
    match = re.search(r'([A-Za-z_$][\w$]*)\s*$', line)
    name = match[1] if match else ''
    clean = statement(line)
    if token == ' <-' and name:
        # Dots in R names are not object-member access.
        return 1.25
    value = -0.15
    if name:
        value += 0.33 + 0.05 * (len(name) >= 2)
        value += 0.08 * (len(name) >= 4) + 0.05 * (len(name) >= 8)
        value -= 0.16 * name.isupper()
        value += 0.23 * name.startswith('$')
        if match.start() and line[match.start() - 1] == '.':
            value -= 0.36
    value -= 0.09 * ('.' in line)
    value += 0.52 * bool(DECLARATION.search(line))
    value += 0.1 * (len(line.split()) <= 2)
    value += 0.33 * bool(re.fullmatch(r'[\w$]+(,\s*[\w$]+)*', clean))
    value -= 0.27 * (line.count('(') > line.count(')'))
    value += 0.21 * bool(PYTHON.search(text))
    value -= 0.08 * bool(MATH.search(text))
    value -= 0.27 * bool(re.search(r'\|\s*\n\s*$', text))
    value += 0.45 * (token == ' :=')
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = before.replace('\\n', '\n').replace('\\r', '\r').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    word = token.strip()
    value = 0.0
    if token in (' =', ' :=', ' <-'):
        value = assignment(token, text, line)
    elif token == '=' or re.match(r'^=[A-Za-z_$]', token):
        code = PYTHON.search(text) or DECLARATION.search(line)
        code = code or re.search(r'\b\w+\.\w+\s*\(', text)
        binding = (re.fullmatch(r'[\w$]+', statement(line))
                   or DECLARATION.search(line))
        if code and binding and not re.search(r'<[A-Za-z][^<>]*$', line):
            value = assignment(' =', text, line)
    elif token == ' =>':
        if re.search(r'(\)|\b[a-zA-Z_]\w*)\s*$', line) and '::' not in line:
            value = 0.65
    elif word in ('print', 'println', 'printf', 'cout', 'echo'):
        content = re.sub(r'^(#|//)\s*', '', statement(line))
        if (not content or word in ('cout', 'println', 'printf')
                or re.search(r'[;{}:]\s*$', content)):
            if word == 'print':
                value = 0.75 if token == 'print' else 1.05
            elif word == 'echo':
                value = 0.6
            else:
                value = 1.05 if word in ('cout', 'println') else 0.8
    elif token == '.log' and re.search(r'\bconsole$', text):
        value = 1.5
    elif token == '.out' and text.endswith('System'):
        value = 1.5
    elif token in ('.Println', '.WriteLine'):
        value = 1.1
    elif token in ('.println', '.Printf'):
        value = 0.75
    elif word in ('fmt', 'Console', 'console'):
        value = 0.7 if word != 'console' else 0.3
    elif token in ('stdio', 'iostream'):
        value = 1.2
    elif token == '_dump' and text.endswith('var'):
        value = 1.2
    elif word == '<<' and re.search(r'\bcout\s*$', text):
        value = 0.85
    elif token == '.com' and text.endswith(('github', 'githubusercontent')):
        value = 2.5
    elif token == '](':
        value = 1.0
    elif token == '#' and text.endswith(('](', '{')):
        value = 1.15
    elif word in ATTRIBUTES and token.startswith(' '):
        if text.rfind('<') > text.rfind('>'):
            value = 0.8
    elif word == 'html' and re.search(r'(<|<!DOCTYPE)\s*$', text):
        value = 1.2
    elif token == '1' and not line.strip():
        previous_line = text.rstrip()
        value = 0.65 if previous_line.endswith((':', '：')) else 0.3
        if previous_line.endswith('References'):
            value = 1.05
    return (doc, (before + token)[-250:]), value

"""Recognize delimiters in structured text; leave ordinary prose near zero.

Negative pulses mark numeric colons, especially date/time stamps, diff hunk
endings, diagnostic gutters, and assigned backtick strings. Positive pulses
mark XML namespace colons and a few XML tag names. SQL dumps and initial
comment lines have separate negative pulses. Runs of middle dots are positive.
Keep only a short text suffix,
resetting it at document boundaries; no token-ID lookup is used.
"""
import re

READS = ()


def activation(token, before):
    if token == ':':
        # Lowercase XML namespaces, not generic types such as Vec<T>.
        if re.search(r'''(?:^|[\s`'">])</?[a-z][a-z0-9_-]*$''', before):
            return 3.0
        m = re.search(r'(\d+)$', before)
        if m:
            n = len(m[1])
            if re.search(r'\b\d{1,2} [A-Z][a-z]{2} \d{4}, \d{2}$', before):
                if re.search(r'Show Tags\s+\d{1,2} \w+ \d{4}, \d{2}$', before):
                    return -6.3
                return -4.3
            # SubRip-style subtitle time ranges.
            if re.search(r'--> \d{2}$', before):
                return -4.1
            if re.search(r'--> \d{2}:\d{2}$', before):
                return -2.7
            if re.search(r'\.[a-z]+:\d+$', before):
                return -0.85 if n <= 2 else -0.5
            if re.search(r'(?:^|\n)\s*\d+$', before):
                return -0.7 if n <= 3 else -0.3
            if re.search(r':\d+$', before):
                return -1.0 if n <= 2 else -0.3
            if n == 2:
                return -0.58
            if n == 1:
                return -0.8 if re.search(r'[{,] \d$', before) else -0.12
            return -0.07
        if re.search(r'--- (?:PASS|FAIL)$', before):
            return -0.8
    if token.strip() == '@@' and re.search(r'\+\d+(?:,\d+)?$', before):
        return -5.6 if '\n' in token else -9.2
    if token == ' INTO' and before.endswith('INSERT'):
        dump = 'Dumping data for table' in before or 'DISABLE KEYS' in before
        return -3.1 if dump else -0.3
    if token in (' |', ' │') and re.search(r'(?:^|\n)\s*\d+$', before):
        return -1.2
    if token in (' `', ' `<') and re.search(r'=\s*$', before):
        return -2.4
    if not before and token == '//\n':
        return -8.25
    if before.endswith(('<', '</')):
        if token == 'xp':  # Property markup.
            return 3.0
        if token == 'xd':  # Editor markup.
            return 1.3
        if token == 'template':
            return 1.3
        if token == 'DOCUMENT':
            return 1.0 if before.endswith('</') else 2.35
    if token == 'ATION' and before.endswith(('<DOCUMENT', '</DOCUMENT')):
        return 8.5
    if token == '··' and (not before or before.endswith('··')):
        return 0.89
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-300:]), value

"""A surface-form detector for adverb endings, not a full grammatical parser.

English -ly and Romance -mente are positive, especially as separate word
pieces. Degree modifiers are stronger than time or discourse adverbs.
'The only/first' contrasts with adverbial uses and gets a negative value.
The constants approximate training averages; word-specific strengths remain.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
DEGREE = set('greatly nearly purely solely substantially considerably lightly'.split())
EXTENT_AND_FOCUS = set('particularly largely closely highly heavily absolutely roughly '
               'merely totally fully slightly'.split())
TIME = set('currently recently previously eventually finally usually daily weekly '
           'early lately formerly frequently rarely quickly slowly suddenly'.split())
ORIGIN_OR_REGULARITY = set('annually monthly regularly normally originally'.split())
DISCOURSE_AND_MODAL = set('alternatively similarly consequently accordingly conversely '
                'additionally actually probably possibly necessarily typically '
                'really certainly'.split())
COPULAS = set('is are was were be been being becomes became'.split())

@lru_cache(maxsize=8192)
def pos(word):
    return wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '')
    _, tail, previous, before, last = carry
    text = prefix.token_strings[-1]
    s = text.strip().lower()
    # Extend the current word only when this token continues it without space.
    match = re.search(r'[A-Za-z]+$', text)
    joined = (tail if match and match.start() == 0 else '')
    joined += match.group() if match else ''
    word = joined.lower()
    split = bool(tail) and text[:1].isalpha()
    value = 0.0
    if s.endswith('ly') and s.isalpha():
        if split:
            roles = pos(word)
            adv = 'adverb' in roles
            noun = 'noun' in roles and not adv
            if s == 'ly':
                value = 2.0 if adv else (-1.4 if noun else 0.85)
            elif s == 'ely':
                value = 1.85 if adv else 0.6
            elif s.endswith('ically'):
                value = 0.43
            elif s.endswith(('ively', 'ously', 'ably')):
                value = 0.45
            elif s == 'ily':
                value = 1.7
            else:
                value = 0.88 if adv else (-0.1 if noun else 0.5)
        else:
            value = 0.58 if 'adverb' in pos(s) else 0.14
            for group, strength in ((DEGREE, 2.15), (EXTENT_AND_FOCUS, 1.4),
                                    (TIME, 0.13), (ORIGIN_OR_REGULARITY, -0.5),
                                    (DISCOURSE_AND_MODAL, 0.08)):
                if s in group:
                    value = strength
                    break
            if s == 'specifically':
                value = 2.55
            elif s == 'especially':
                value = 0.0 if last.rstrip().endswith(',') else 1.4
            elif s == 'only':
                value = 0.3 if previous != 'the' else (
                    -1.5 if before in COPULAS else -1.0)
            elif s == 'likely':
                value = -0.23
    elif split and s.endswith('mente'):
        value = 1.25
    elif split and s in ('ement', 'lement') and 'noun' not in pos(word):
        value = 0.7
    elif split and s in ('ley', 'lyn'):
        value = 1.2
    elif split and s == 'y' and tail.lower().endswith('l'):
        value = 3.5
    elif s == 'first':
        value = -0.05 if previous != 'the' else (
            -1.3 if before in COPULAS else -0.53)
    elif s == 'much' and previous == 'very':
        value = 3.0
    elif s == 'longer' and previous == 'no':
        value = 0.8
    # Retain the partial word and immediate word context for the next token.
    return (doc, joined, word or previous,
            before if split else previous, text), value

"""A modern-year-prefix detector with a few smaller spelling responses.

The main positive pulse is on the third digit of 201/202.  Other branches
recognize a separately tokenized 'ox' syllable, package names, and nonbreaking
spaces.  Repeated middle dots and a document's opening 'Title:' have negative
responses.  These are separate surface patterns, not one semantic category.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if position else ''
    word = token.strip().lower()
    value = 0.0

    if position >= 2 and tuple(prefix.token_strings[-3:-1]) == ('2', '0'):
        if token in ('1', '2'):
            value = 1.15 if token == '1' else 1.53
            if position >= 3 and prefix.token_strings[-4].isdigit():
                value *= 0.35

    # Spelled-out ox/oxy/oxid pieces, especially inside chemical names.
    if word in ('ox', 'oxy', 'oxid'):
        value = 1.35 if token == word else 0.95
    elif word in ('oxide', 'oxides'):
        value = 0.7
    elif word == 'oxygen':
        value = 0.4
    elif token in ('x', 'xy') and previous.lower().endswith('o'):
        value = 0.9
    elif word in ('ide', 'ides', 'id') and previous.strip().lower().endswith('ox'):
        value = 0.8

    # Software package words and path segments.
    package = word.lstrip('/.')
    if package in ('pkg', 'package', 'packages'):
        value = 0.8 if package == 'pkg' or word.startswith('/') else 0.3

    if token == '\xa0':
        if '\n' in previous:
            value = 0.5
        elif previous.isspace():
            value = -0.05
        elif previous.rstrip().endswith(('.', ':', ';', '!', '?')):
            value = 0.23
        else:
            value = 0.08
    elif token == '··' and previous == '··':
        value = -0.61
    elif position == 1 and previous == 'Title' and token == ':':
        value = -2.78

    return (doc, position), value

programs.haiku:
"""Fires on the decade digit of a year, and weakly on a few word pieces.

What it responds to, in plain terms:
1. Years written as digits. Qwen reads digits one at a time, so "2019" is the tokens
   "2", "0", "1", "9". The component fires on the third digit when it is 1 or 2 (201x and
   202x years): strongly on "2" (about 1.45) and a bit less on "1" (about 1.15). The digit
   "0" after "20" (2000s) and the digits 3-9 do not fire, and neither do years that start
   with "19" or "18". The "20" must be in the same document as the digit.
2. Word pieces built on "ox" (ox, oxy, oxide, oxygen, epoxy, nox): about 0.85.
3. Software package paths: "pkg" and "/packages" (about 0.8); the words "package" and
   "packages" only weakly (about 0.3).
Everywhere else the activation is about zero, so the program predicts 0.
"""

READS = ()

OXYGEN_PIECES = {"ox", "oxy", "oxid", "oxide", "oxygen", "nox", "epoxy", "dioxide"}
PKG_PIECES = {"pkg", "/pkg", "_pkg", "/packages", "/package"}
PACKAGE_WORDS = {"package", "packages"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    t = prefix.position
    same_doc = t >= 2 and prefix.document_ids[t - 2] == prefix.document_ids[t]
    if same_doc and tokens[t - 2] == "2" and tokens[t - 1] == "0":
        if tokens[t] == "2":
            return carry, 1.45
        if tokens[t] == "1":
            return carry, 1.15
    word = tokens[t].strip().lower()
    if word in OXYGEN_PIECES:
        return carry, 0.85
    if word in PKG_PIECES:
        return carry, 0.8
    if word in PACKAGE_WORDS:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""Wisdom/wit spellings, and a few related East Asian written forms.

This is a sparse lexical response, not a general intelligence detector.  It
responds most strongly to wisdom, 智/慧 (wisdom), and their split-token forms.
Weaker responses mark wit, written characters, and numerical digits.
A small document-start bias becomes strongly negative for opening quotes or
literal escape sequences. Doubled middle-dot filler is also negative.
Other context-specific responses are omitted.
"""
import codecs
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        previous, tail, pending, opening = '', '', b'', None
    else:
        _, previous, tail, pending, opening = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    s = text.strip()
    lower = s.lower()
    continuation = bool(text) and text[0].isalpha() and not text[0].isspace()
    word = (tail + text if continuation else text).lower()
    match = re.search(r'[a-z]+$', word)
    next_tail = match.group()[-24:] if match else ''
    value = -0.1 if start else 0.0
    opening = s if start else opening if opening == s else None
    if opening == s and s:
        if s == r'\t':
            value = -4.75
        elif s == r'\n':
            value = -2.44
        elif s == r'\"':
            value = -3.27
        elif s.endswith('\\'):
            value = -1.1
        elif s[0] == '"' or unicodedata.category(s[0]) == 'Pi':
            value = -0.85
    if s == '··':
        value = -2.2

    # Wisdom and blessing ideographs; larger compounds are not all equivalent.
    if s in {'智', '慧', '智慧'}:
        value = 6.3
    elif s == '惠':
        value = 3.7
    elif s == '恵':
        value = 5.7
    elif s == '志':
        value = 1.1
    elif s == '智力':
        value = 2.3
    elif s == '智能':
        value = 0.9
    elif s == '文字':
        value = 2.3
    elif s == '数字':
        value = 1.4
    elif s == '字' and previous.strip() in {'数', '文'}:
        value = 2.6
    elif pending.endswith('智'.encode()[:2]):
        # The token has supplied the first two bytes, but not the whole glyph.
        value = 5.4

    # The response also follows these Latin spellings across token boundaries.
    elif lower == 'wisdom':
        value = 6.2 if s[:1].isupper() else 4.9
    elif word.endswith('wisdom') and lower == 'dom':
        value = 13.5
    elif lower == 'wis':
        value = 2.2 if text.startswith(' ') else 5.0 if not tail else 0.0
    elif lower == 'wise':
        value = 1.5 if not tail or text.startswith(' ') else 0.3
        if tail == 'un':
            value = 2.2
    elif lower in {'wit', 'witty'}:
        value = 0.75
    elif lower == 'witt':
        value = 2.2
    elif continuation and tail.endswith('w'):
        if lower in {'itt', 'itted'}:
            value = 3.6
        elif lower in {'ise', 'iser', 'isest'}:
            value = 2.7
        elif lower.startswith('iss') or lower == 'is':
            value = 1.0
        elif lower == 'its':
            value = 1.4
    # Spelling, not meaning: Indonesian wisata shares the wis- prefix.
    elif continuation and tail.endswith('wis') and lower == 'ata':
        value = 3.3
    elif lower == 'digits' and text.startswith(' '):
        value = 0.65
    elif lower == 'digit' and text.startswith(' '):
        value = 0.2
        if previous.strip().lower() in {'random', 'units', 'tens', 'hundreds'}:
            value = 1.1

    return (doc, text, next_tail, pending, opening), value

programs.haiku:
"""Detector for the word "wisdom" and its relatives, plus a few CJK and digit words.

The component reads a word as it is spelled. It keeps the letters of the current word so
far, lowercased, across subword tokens, so "Wis" followed by "dom" forms "wisdom". It fires
on wisdom words: "wisdom" (strongest), "wise", "wis" (the start of wisdom or Wisconsin),
"wit", "witty", "wisely", "wisconsin". It also fires on Chinese and Korean words for
wisdom and intelligence (智慧, 智, 智能, 智力, 惠, 혜), on 志 and 文字, and weakly on
"digit(s)" words. Everything else predicts 0. Values are typical activations in the data.
"""

WORD_VALUES = {
    "wisdom": 7.0, "wise": 1.3, "wis": 1.5, "wisconsin": 0.5, "wisely": 0.4,
    "wit": 0.7, "witty": 0.9,
}
TOKEN_VALUES = {
    "智": 6.5, "智慧": 6.0, "智能": 1.0, "智力": 1.5, "志": 1.1, "惠": 3.0, "혜": 5.0,
    "文字": 2.4, "数字": 1.5, "digits": 0.8, "digit": 0.3,
}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    if text in TOKEN_VALUES:
        return "", TOKEN_VALUES[text]
    # Extend the current word if this token continues it (no leading space, letters only).
    if carry and token[:1].isalpha() and text.isalpha():
        word = carry + text.lower()
    elif text.isalpha():
        word = text.lower()
    else:
        return "", 0.0
    return word, WORD_VALUES.get(word, 0.0)

programs.sol:
"""A local spelling-and-construction detector for 'all'.

Predict a negative response on English 'all' and Germanic inflections,
with weaker responses to an internal syllable. Italian all-/alle/alla
are prepositions instead. Fixed constructions ('first of all', 'at all',
'after all') and the preceding word change the response. Also recognize
quantifying 'of' phrases and a few other words expressing totality.
This approximates the dominant pattern, not every lexical exception.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()
GERMANIC_FORMS = {
    'alle': -5.3, 'allen': -5.3, 'allem': -2.3,
    'alles': -2.8, 'aller': -1.4, 'alla': -5.3,
}
OTHER_TOTALITY = {
    'total': -0.3, 'everything': 0.3, '所有': -0.7,
    '全': 0.65, 'forall': -2.4, '∀': -1.2,
}
QUANTITIES = set('lot lots variety majority bunch plethora array'.split())


def response(token, before):
    word = token.strip().lower()
    words = re.findall(r'[^\W\d_]+', before.lower())
    adjacent = re.search(r'([^\W\d_]+)\s*$', before.lower())
    last = adjacent.group(1) if adjacent else ''
    if word == 'of' and last in QUANTITIES:
        return -1.2 if last in ('lot', 'lots') else -1.7
    if re.search(r'\bAl$', before) and word in ('les', 'lem', 'len', 'ler'):
        return -8.0
    if word not in GERMANIC_FORMS and word not in ('all', '(all', '_all', '-all'):
        return OTHER_TOTALITY.get(word, -0.002)

    # Lowercase continuations such as crystall- are not whole-word 'all'.
    if (token[:1].islower() and before[-1:].isascii()
            and before[-1:].isalpha() and not re.search(r'\\[nt]$', before)):
        return 0.3
    scores = {
        lang: sum(min(5.5, zipf_frequency(w, lang)) for w in words[-16:])
        for lang in ('en', 'de', 'it', 'sv', 'nl', 'fr')
    }
    language = max(scores, key=scores.get)
    if language == 'it' and word in ('all', 'alle', 'alla'):
        return 1.2 if word == 'alla' else 2.3
    if language == 'fr':
        return -0.8
    if word in GERMANIC_FORMS:
        if token.strip() == 'Allen':
            return -1.6  # the personal name, rather than an inflection
        return GERMANIC_FORMS[word]
    if not before:
        return -1.05
    if token == 'All' and before[-1:].isalpha():
        return -4.5  # camel-case names ending in All
    if before.endswith('__'):
        return 0.0  # Python's __all__ identifier
    if re.search(r'\bfirst\s+of\s*$', before, re.I):
        return 2.7
    if last == 'at':
        if len(words) > 1 and 'look' in wordnet.base_forms(words[-2]):
            return -3.2
        return 0.0
    if last == 'after':
        return -5.8
    if last == 'of':
        if re.search(r'(?:\bset|\bmost|\bbest|%|\bpercent)\s+of\s*$', before, re.I):
            return -0.9
        return -2.8
    if last in ('not', 'or', 'can', 'we', 'they', 'almost', 'nearly'):
        return -1.9
    if last in ('and', 'with', 'that', 'which'):
        return -4.3
    if last in ('where', 'when', 'through', 'about', 'out'):
        return -5.0
    if word == 'all' and 'verb' in wordnet.parts_of_speech(last):
        return -4.2
    return -2.2 if word == '_all' else -3.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-160:]), response(token, before)

programs.haiku:
"""Negative "all"-quantifier detector for layers.1.mlp.down_proj:3719.

The component is silent on almost every token. It goes strongly negative on the
English quantifier "all" when it is used as a determiner or pronoun, as in
"lost all hope", "in spite of all the", "all of them" (about -3.4 typically, down to
-8 in the strongest cases). The German forms "alle/alles/allen/aller/allem" (all, every)
get a similar negative value. Three exceptions:
  - the idiom "at all" ("not at all") is about 0;
  - "after all" is more negative (about -6);
  - "First of all" (sentence opener) is weakly positive.
A run of dot leaders (the token "··") gives a small negative value too.
Everything else predicts 0.
"""

READS = ()

EN_ALL = {" all", " All", "All", " ALL", "ALL", "all"}
DE_ALL = {" alle", " alles", " allen", " aller", " allem", " Alle"}
DOT_LEADER = {"··"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    n = len(prefix)
    same_doc = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    prev2 = prefix.token_strings[-3].strip().lower() if n > 2 and same_doc and prefix.document_ids[-3] == prefix.document_ids[-1] else ""
    if tok in EN_ALL:
        if prev == "at":
            return carry, 0.0
        if prev == "of" and prev2 == "first":
            return carry, 2.5
        if prev == "after":
            return carry, -6.0
        return carry, -3.4
    if tok in DE_ALL:
        return carry, -3.5
    if tok in DOT_LEADER:
        return carry, -1.1
    return carry, 0.0

programs.sol:
"""A coarse token-shape and document-position approximation.

Multi-character tokens at a document's beginning usually get a negative
estimate, except very common English words preceded by a space. Elsewhere,
the estimate is small: it grows later in the document and after alphabetic
tokens, with a further increase for multi-character Han tokens. These broad
averages deliberately leave out the component's token-specific variation.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def token_properties(text):
    word = text.strip()
    frequency = zipf_frequency(word.lower(), 'en') if word.isalpha() else 0.0
    return len(word), frequency, bool(regex.search(r'\p{Script=Han}', word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    position = 0 if first else carry[1] + 1
    text = prefix.token_strings[-1]
    length, frequency, han = token_properties(text)
    previous_is_word = not first and prefix.token_strings[-2].strip().isalpha()

    if first and length >= 2:
        if frequency <= 5.01:
            value = -0.1606
        elif not text.startswith(' '):
            value = -0.0902
        elif frequency > 7.36:
            value = 0.1532
        else:
            value = -0.0155
    elif position < 88:
        value = 0.0052 if previous_is_word else -0.0012
    elif not previous_is_word:
        value = 0.0062
    elif frequency > 5.93:
        value = 0.0069
    elif length < 2:
        value = 0.0085
    elif han:
        value = 0.0345
    else:
        value = 0.0178 if text.startswith(' ') else 0.0104
    return (doc, position), value

"""Surface-form approximation to Japanese -te and Korean connective endings.

Short, separately tokenized endings get the largest negative response.  Merged
verb forms are weaker; particles and conjunctions resembling them are weaker
still. Korean stem syllables modulate the separated vowel endings. A short
byte tail preserves split characters and resets at document boundaries.
"""
READS = ()

# Japanese connective allomorphs and compound case particles.
TE_ENDINGS = {
    'して': -10.5, 'って': -11.0, 'て': -7.2,
    'いて': -6.7, 'えて': -9.3, 'んで': -8.5,
}
COMPOUND_PARTICLES = {
    'として': -3.4, 'について': -3.4, 'によって': -1.8,
    'に関して': -0.8, 'に対して': -0.8,
}
# Conjunctions, adverbs and stems which only resemble these endings.
NONCONNECTIVES = {
    'とても', 'そして', 'なんて', 'すべて', '全て', '当て', '捨て', '전혀',
}
KOREAN_ENDINGS = {
    '어': -6.5, '아': -5.5, '여': -7.4, '해': -5.3,
    '려': -4.5, '러': -4.6, '고': -2.9, '서': -1.7,
    '며': -1.0, '라': -1.4, '와': -0.65, '써': -3.6,
}


def predict(text, before=''):
    t = text.strip()
    previous = before[-1:] or '\0'
    if t == 'して' and previous == 'ま':
        return -3.0  # polite -mashite, not plain -shite
    if t == 'いて' and previous in 'てで':
        return -3.5  # auxiliary iru after a preceding connective
    if t in {'어', '아', '여', '고'} and t == text:
        return korean_suffix(t, previous)
    if t in TE_ENDINGS:
        return TE_ENDINGS[t]
    if t in NONCONNECTIVES:
        return -0.3
    if t in COMPOUND_PARTICLES:
        return COMPOUND_PARTICLES[t]
    if t.endswith('て'):
        if t.endswith(('なくて', 'まして', 'していて', 'あって')):
            return -3.2
        if t == 'くて':
            return -4.8
        return -6.7
    if t.endswith('で'):
        if t.endswith('んで'):
            return -8.0
        return -0.5
    if t.endswith(('ても', 'ために', 'ずに', 'ながら')):
        return -1.8
    if t in KOREAN_ENDINGS:
        if text.startswith(' ') and t not in {'해', '서'}:
            return -1.0
        return KOREAN_ENDINGS[t]
    # Korean contractions in -yeo: gyeo, kyeo, chyeo, jyeo, pyeo, etc.
    if t and all('가' <= c <= '힣' for c in t):
        last = ord(t[-1]) - ord('가')
        vowel, coda = (last // 28) % 21, last % 28
        if t == '하여':
            return -4.2
        if not coda and vowel == 6 and t[-1] not in '녀며':
            return -5.8
        if t.endswith(('어', '아', '워', '봐')):
            return -5.5
        if t.endswith('해'):
            return -2.0 if t in {'위해', '통해', '이해', '대해', '의해'} else -5.0
        if t.endswith(('고', '서')) and not t.endswith(('에서', '께서')):
            return -2.0
        if t.endswith('며'):
            return -0.6
    return 0.0


def korean_suffix(ending, previous):
    """A connective is strong after a compatible stem, weak after other syllables."""
    if not '가' <= previous <= '힣':
        return -2.5
    n = ord(previous) - ord('가')
    vowel, final = (n // 28) % 21, n % 28
    # Unicode Hangul composition indices: l, l+h, n, ng; oe, u, wi, o.
    L, LH, N, NG = 8, 15, 4, 21
    OE, U, WI, O = 11, 13, 16, 8
    if ending == '어':
        if final in (L, LH):
            return -11.0
        if final:
            return -7.0
        if vowel == OE:
            return -12.0
        return -6.5 if previous == '이' or vowel in (U, WI) else -2.5
    if ending == '아':
        if final:
            return -4.0 if final in (N, NG) else -9.5
        return -10.0 if vowel == O else -1.5
    if ending == '여':
        if final == L:
            return -14.0
        return -10.0 if previous in '보하' else -4.0
    if previous in '었였했겠다' or final == NG:  # past/modal endings
        return -0.9
    return -7.5 if final == L else -3.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    value = predict(prefix.token_strings[-1], tail.decode('utf8', 'ignore'))
    tail = (tail + prefix.token_bytes[-1])[-32:]
    # Dwae is the contraction of doe + eo, sometimes split across byte tokens.
    if tail.endswith('돼'.encode('utf8')):
        value = -10.5
    return (doc, tail), value

programs.haiku:
"""Digit-2 detector, with the number 12 spelled as a word.

Fires on a '2' written right after a digit, when that digit is odd: '12', '32', '52',
'72', '92' fire, '1' most of all. A '2' after an even digit (0, 2) stays silent; after 4, 6 or 8 it
fires weakly. A '2' deeper inside a longer number fires about 0.7 times as strongly. The
words 'twelve' and 'December' (the 12th month) also fire.
"""
READS = ()
DIGITS = set("0123456789")
WORDS_FOR_12 = {" twelve": 4.5, " Twelve": 4.5, " December": 2.3}


def step(carry, prefix, upstream):
    toks, docs = prefix.token_strings, prefix.document_ids
    if toks[-1] in WORDS_FOR_12:
        return carry, WORDS_FOR_12[toks[-1]]
    if len(toks) < 2 or toks[-1] != "2" or docs[-2] != docs[-1] or toks[-2] not in DIGITS:
        return carry, 0.0
    prev = int(toks[-2])
    if prev == 1:
        value = 4.0
    elif prev % 2 == 1:
        value = 2.4
    else:
        value = 0.6 if prev in (4, 6, 8) else 0.0
    if len(toks) >= 3 and toks[-3] in DIGITS and docs[-3] == docs[-1]:
        value *= 0.7
    return carry, value

programs.sol:
"""Approximate a spelling detector for the consonant cluster 'gr'.

It responds to short gr fragments and especially to g|r across a token split.
A few common word families have weaker or stronger responses. The following
fragment can retain some response. Word breaks, camel-case breaks, and document
boundaries stop that continuation. Transliteration covers other alphabets too;
Katakana グ is treated as g.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=20000)
def spelling(token):
    return anyascii(token.replace('グ', 'g')).lower()


def gr_fragment(word, token, continued):
    """Response when gr is already present in this token's spelling."""
    spaced = token[:1].isspace()
    if not word.startswith('gr'):
        return 0.6 if word.endswith('gr') else 0.08
    if word == 'gr':
        if continued:
            return 2.5
        return 1.5 if token.strip()[:1].isupper() else 1.8
    if word.startswith(('grant', 'grandfather', 'grandmother',
                        'grandparent', 'grandchild')):
        return -0.25
    if word in ('gran', 'grande', 'grandes', 'grandi'):
        return 3.2
    if word.startswith(('grand', 'grund')):
        return 2.0
    if word == 'great':
        return 0.6 if spaced else 1.0
    if word.startswith('great'):
        return 0.15
    if word.startswith('green'):
        return 1.35 if spaced else 1.8
    if word.startswith('ground'):
        return 0.85
    if word.startswith('gross'):
        return 0.8 if 'ß' in token else 2.7
    if word.startswith('grass'):
        return 1.5
    if word.startswith('grade'):
        return 1.15 if spaced else 2.0
    if word.startswith(('group', 'grow', 'graph')):
        return 0.13
    if word.startswith('gram'):
        return 0.35
    if word.startswith(('griev', 'graft')):
        return -0.8
    if len(word) == 3:
        return 1.7
    return 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, False, True)
    _, previous, word, crossed, lower_end, ascii_end = carry
    token = prefix.token_strings[-1]
    text = spelling(token)
    start = re.match('[a-z]+', text)
    first = re.search('[a-z]+', text)
    chunk = first.group() if first else ''
    continued = bool(start and word)
    if token[:1].isupper() and lower_end:
        continued = False

    value = gr_fragment(chunk, token, continued) if 'gr' in chunk else 0.0
    crossing_now = False
    if continued:
        if previous.endswith('g') and chunk.startswith('r'):
            crossing_now = True
            ascii_pair = token.isascii() and ascii_end
            if len(chunk) == 1:
                value = 6.0 if ascii_pair else 3.5
            elif len(chunk) >= 4 and token[:1].isupper():
                value = 0.7
            elif ascii_pair:
                if chunk[1] in 'ao':
                    value = 3.5
                elif chunk[1] in 'iu':
                    value = 2.8
                else:
                    value = 1.8
            else:
                value = 2.5 if chunk[1] == 'a' else 1.3
                if chunk[1] == 'e':
                    value = 0.6
        elif previous.endswith('gr'):
            crossing_now = True
            if len(previous) == 3 and previous[0] in 'aeiou':
                value = 4.7 if chunk.startswith('a') else 1.3
            elif previous == 'gr':
                value = 2.1 if len(word) > 2 else 1.5
            else:
                value = 0.5
        elif crossed:
            distance = len(word) - word.rfind('gr') - 2
            if 'gr' in word and distance == 0:
                value = 3.4
            elif 'gr' in word and distance <= 2:
                value = 0.7 if distance == 1 else 0.35
            elif 'gr' in word and distance <= 5:
                value = 0.25
        elif 'gr' in previous:
            distance = len(previous) - previous.rfind('gr') - 2
            value = 1.1 if distance <= 1 else 0.25
        elif value == 0 and 'g' in previous[-4:] and 'r' in chunk[:3]:
            value = 0.2

    joined = word + text if continued else text
    tail = re.search('[a-z]+$', joined)
    word = tail.group()[-40:] if tail else ''
    tail = re.search('[a-z]+$', text)
    previous = tail.group() if tail else ''
    carry = (doc, previous, word, crossing_now,
             token[-1:].islower(), token.isascii())
    return carry, value

"""Surface rules for a sparse, mostly CJK quantity/comparison response.

Selected amount, rank, variety and waiting expressions get positive values,
often only after short modifiers. These families recur among large training
activations. Smaller rules cover English counts/equal measures, fate and
aspiration words, negative cash labels and symbol-name suffixes. Separate
opening-position rules handle Title headers and initial separator-token runs.
This is a partial approximation; other lexical responses are mostly left zero.
"""
import codecs
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=32768)
def simplify(text):
    return _SIMPLIFY.convert(text)


# Short modifiers of amount, degree, variety, or availability.
MODIFIERS = (
    '高', '低', '大', '小', '多', '少', '同', '同一', '不同',
    '无', '没', '有', '超', '过', '满', '各', '某', '何',
    '短', '长', '足够', '中等', '高等', '低等',
)
MEASURES = {
    '容量', '负荷', '风险', '频率', '电压', '时间',
    '浓度', '角度', '概率', '功率', '附加值',
}
KINDS = {'类型', '领域', '领域的', '属性', '性别'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, previous, position, opening_run, pending = '', '', 0, None, b''
    else:
        _, old, previous, position, opening_run, pending = carry
    raw = prefix.token_strings[-1]
    if position == 0:
        opening_run = raw
    elif raw != opening_run:
        opening_run = None
    # Finish characters split across byte-level tokens, without looking ahead.
    data = pending + prefix.token_bytes[-1]
    decoded, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    normalized = simplify(decoded)
    word = normalized.strip()
    context = old
    modified = context.endswith(MODIFIERS)
    value = 0.0

    if word in {'数量', '重量', '种类', '的数量'}:
        value = 0.6
        if word == '的数量':
            value = 1.25
        elif word == '数量' and modified:
            value = 1.8
    elif word in MEASURES:
        value = 0.85 if modified else 0.0
        if word == '时间' and context.endswith('长'):
            value = 0.15
    elif word == '一种' and context.endswith(('同', '某')):  # Same/some kind.
        value = 2.0 if context.endswith('同') else 0.6
    elif word in KINDS:
        value = 0.65 if modified else 0.07
    elif word == '量':  # Amount/measure suffix, as in 数量 and 常量.
        value = 0.08
        if context.endswith('数'):
            value = 2.6
        elif context.endswith(('过', '分', '差', '全', '份')):
            value = 1.15
        elif context.endswith(('常', '加', '音', '按')):
            value = 0.75
    elif word in {'额', '钱', '值', '薪'}:  # Amount, money, value, wage.
        value = 1.1 if modified or context.endswith(('多少', '亏')) else 0.02
    elif word in {'高等', '同等'}:  # Higher rank; equal rank.
        value = 1.5
    elif word in {'等等', '等地'}:  # Etcetera / and other places.
        value = 0.9
    elif word == '等':
        value = 0.0
        if context.endswith(('中', '上', '下', '高', '低')):
            value = 1.9
        elif modified or context.endswith(
            ('不', '相', '何', '该', '还在', '稍', '得', '可', '我')
        ):
            value = 0.9
    elif word == '等待':  # Waiting, rather than 等 used to end a list.
        value = 0.55
    elif word in {'待', '着', '不到', '不起', '不及'} and context.endswith('等'):
        value = 1.8 if word in {'不起', '不及'} else 1.0
    elif word in {'样', '様', '样的'}:  # Kind/style/variety suffixes.
        if context.endswith('同'):
            value = 1.9
        elif context.endswith(('多', '各')):
            value = 1.0
        elif context.endswith(('一', '哪', '啥', '怎', '什么', '怎么')):
            value = 0.4
    elif word == '种' and decoded.strip() == '種':
        if context.endswith('多'):
            value = 0.85
        elif context.endswith(('某', '何')):
            value = 0.5
    elif word == '々' and context.endswith('等'):
        value = 1.7
    elif word == '源' and context.endswith('同'):
        value = 0.75
    elif word in {'命', '命运'}:  # Life/fate, and 命 in compound words.
        value = 0.4 if word == '命' else 1.1
        if word == '命' and context.endswith(('没', '无', '待', '绝')):
            value = 1.7
    elif word == '志' and context.endswith(('有', '众')):  # Aspiration/will.
        value = 1.4
    # Symbol names: equals sign, colon, question mark, negative sign, etc.
    elif word == '号' and context.endswith(('等', '冒', '问', '负', '代', '符')):
        value = -0.65
    elif word in {'人民币', '现金'}:
        value = -0.9 if word == '人民币' else -0.45

    english = raw.strip().lower()
    preceding = old.rstrip().lower()
    last_word = preceding.rsplit(None, 1)[-1] if preceding else ''
    noun = english[:-3] + 'y' if english.endswith('ies') else english.removesuffix('s')
    if raw.startswith(' ') and english.isascii():
        if english == 'number':
            value = 0.22 if preceding.endswith('total') else 0.08
        elif english == 'effect':
            value = 0.4 if preceding.endswith(('has no', 'have no', 'had no')) else -0.11
        elif noun in {'volume', 'magnitude', 'value', 'angle',
                                      'distance', 'length', 'quantity'}:
            equal_measure = last_word == 'equal' or (
                english == 'magnitude' and last_word == 'same'
            )
            value = 0.8 if equal_measure else (
                0.0 if english == 'quantity' else -0.04
            )
        elif english in {'risk', 'frequency'}:
            value = -0.08

    # Initial-position effects are not the quantity feature.
    if position == 0:
        value = 0.96 if raw == 'Title' else -0.11
    if len(raw) >= 2 and set(raw) == {'·'} and opening_run == raw:
        value = -2.2
    elif raw and set(raw) == {'^'} and len(raw) >= 3 and opening_run == raw:
        value = -1.85
    elif position == 1 and previous == 'Title' and raw == ':':
        value = -4.42

    carry = (doc, (old + normalized)[-40:], raw, position + 1, opening_run, pending)
    return carry, float(value)

"""Approximate a negative response to sustained Finnish/Finnic text.

Completed words vote for Finnish against other European languages using
word frequencies. Unfamiliar Estonian spellings with õ or öö also vote.
The fading language score gates a negative letter response, stronger at
word beginnings. Document starts and repeated middle-dot separators have
separate corrections. It misses isolated name/syllable spikes without
accumulated language evidence; no token identities are memorized.
"""
from functools import lru_cache
from math import log10
from wordfreq import get_frequency_dict

READS = ()
OTHER_LANGUAGES = (
    'en', 'de', 'fr', 'es', 'it', 'sv', 'nb', 'nl', 'pl', 'hu', 'tr', 'pt'
)
FREQUENCIES = {lang: get_frequency_dict(lang)
               for lang in ('fi',) + OTHER_LANGUAGES}


@lru_cache(maxsize=50000)
def finnish_evidence(word):
    if len(word) < 2:
        return 0.0
    finnish = FREQUENCIES['fi'].get(word, 0.0)
    other = max(FREQUENCIES[lang].get(word, 0.0)
                for lang in OTHER_LANGUAGES)
    # wordfreq has no Estonian dictionary; use its distinctive spelling.
    if other < 1e-6 and ('õ' in word or 'öö' in word):
        return 3.0
    if max(finnish, other) < 1e-6:
        return 0.0
    ratio = max(finnish, 1e-9) / max(other, 1e-9)
    return max(-3.0, min(3.0, log10(ratio) - 0.8))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0.0)
    _, word, language_score = carry
    text = prefix.token_strings[-1]
    word_start = not word or not text[:1].isalpha()

    for char in text:
        if char.isalpha():
            word = (word + char.lower())[-60:]
        elif word:
            language_score = max(-3.0, min(
                9.0, 0.95 * language_score + finnish_evidence(word)))
            word = ''

    confidence = max(0.0, min(1.0, language_score / 4.0))
    has_letters = any('a' <= c.lower() <= 'z' or c.lower() in 'äöõüå'
                      for c in text)
    if has_letters:
        strength = 5.5 if word_start else 3.9
    else:
        strength = 0.16 if any(c in '.,:;!?' for c in text) else 0.0
    value = -confidence * strength - (0.155 if first else 0.0)

    if not first and len(text) >= 2 and set(text) == {'·'}:
        previous = prefix.token_strings[-2]
        if previous and set(previous) == {'·'}:
            value = -1.37
    return (doc, word, language_score), float(value)

"""A sparse ASCII-calculation signal, plus a small document-initial bias.

Compact algebra drills amplify operators, variables and quantity introductions.
Long explanations, chat and code do not get that amplification. Probability
questions, unit conversions and mathematical 'terms' phrases have separate
rules. Most tokens, including digits, predict zero. At a document's first
position, English verbs/adjectives and punctuation get small positive estimates.
"""
import re
import wordnet

READS = ()

# Standard mass, volume and time units, including density notation.
UNIT_END = re.compile(
    r'\b(?:[mkcd]?g|oz|lbs?|liters?|litres?|seconds?|meters?|tsp|tbsp|gallons?)$'
    r'|\b(?:kg|g|oz|st|tn|t|lb)/(?:l|gal|ml|m³|dm³|cm³|metric)'
    r'(?: (?:tsp|tbsp))?$')


def math_strength(text, chat):
    """Distinguish terse formulas and drills from prose about mathematics."""
    if chat or re.search(r'\\|\$|```|\b(?:return|import|public)\b', text):
        return 0.0
    if re.search(r'\b(?:Wait|Hmm|Thus|Hence|Therefore|Similarly|we)\b|Let me', text):
        return 0.0
    long_words = re.findall(r'[A-Za-z]{4,}', text)
    if sum(map(len, long_words)) >= 0.25 * max(len(text), 80):
        return 0.0
    if re.search(r'\bLet [a-z](?:\([a-z]\))?(?: (?:=|be\b)|$)', text):
        return 1.0
    if re.search(r'\bSuppose (?:[-+0-9]|[a-z] ?[=+*^\-])', text):
        return 1.0
    if re.search(r'(?:^|\n)(?:Question:\n)?Solve [-+0-9a-z ]', text):
        return 1.0
    return 0.2 if re.search(r'\*[a-z]\b|\b[a-z]\*\*|Simplify', text) else 0.0


def calculation(text, token, chat):
    if token == ' prob' and re.search(r'(?: is|Give|Calculate)$', text):
        return 7.0
    if token == ' of' and text.endswith(' prob'):
        return 4.5
    if token == ' to' and UNIT_END.search(text) and any(c.isdigit() for c in text[-100:]):
        return 0.5
    if token == ' terms':
        if re.search(r'(?:lowest|simplest)$', text):
            return 3.5
        if text.endswith('like'):
            return 0.7
        return 0.3 if text.endswith('in') else 0.0
    if token == ' form' and re.search(r'(?:in the|in a)$', text):
        return 0.1

    # Each rule gives an ordinary-text baseline and a full drill response.
    base, peak = 0.0, 0.0
    if '**' in token and re.search(r'(?<![A-Za-z])[a-z0-9]$|\)$', text):
        base, peak = -0.2, 6.7
    elif re.fullmatch(r'\*[a-z]', token) or (
            re.fullmatch(r'[a-z]', token) and text.endswith('*')):
        base, peak = 0.15, 6.3
    elif re.fullmatch(r'\([a-z]', token):
        peak = 6.0
    elif token == '(' and re.search(r'[a-z]$', text):
        peak = 4.0
    elif re.fullmatch(r' [a-z]', token):
        peak = 4.4 if re.search(
            r'(?:Let|Give|Calculate|Determine|What is|of|Find|Round)$', text) else 2.3
    elif re.fullmatch(r'[a-z]', token) and text.endswith('-'):
        base, peak = -0.1, 5.0
    elif token == ' of' and text.endswith(' derivative'):
        base, peak = -0.4, 7.7
    elif token in (' derivative', ' nearest', ' closest'):
        base, peak = -0.2, 5.3
    elif token == ' to' and re.search(r'(?:nearest|closest)$', text):
        base, peak = -0.2, 8.0
    elif token == ' to' and text.endswith('rounded'):
        peak = 2.4
    elif token == ' Let':
        base, peak = -0.2, 7.1
    elif token == ' Give':
        base, peak = 0.5, 8.8
    elif token in (' Calculate', ' Determine', ' Solve', ' Find', ' Round', ' Factor'):
        peak = 2.7
    elif token in (' Suppose', ' assuming') or (token == 'pose' and text.endswith('Sup')):
        peak = 5.0
    elif token in (' +', ' -', ' =', '(-'):
        peak = 1.8
    elif token == ' be' and re.search(r'Let [a-z](?:\([a-z]\))?$', text):
        peak = 4.2
    elif token == ' is' and re.search(r'(?:What|Which)$', text):
        peak = 4.2
    elif token == ' What':
        peak = 3.3
    elif token in ('.', ').'):
        peak = 2.2
    elif token == ' ':
        peak = 1.1
    else:
        return 0.0
    strength = math_strength(text, chat)
    return peak * strength if strength else base


def initial(token):
    if token == '<|endoftext|>':
        return 6.681
    word = token.strip()
    if token.startswith(' ') and word.isascii() and word.isalpha():
        pos = wordnet.parts_of_speech(word.lower())
        value = max((0.3 if 'verb' in pos else 0.0),
                    (0.2 if 'adjective' in pos else 0.0),
                    (0.1 if 'adverb' in pos else 0.0))
        return value * (0.5 if 'noun' in pos else 1.0)
    return 0.2 if token.isascii() and not any(c.isalnum() for c in token) else 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    text, chat = ('', False) if fresh else carry[1:]
    chat = chat or token == '<|im_start|>'
    value = initial(token) if fresh else calculation(text, token, chat)
    return (doc, (text + token)[-400:], chat), float(value)

programs.haiku:
"""Quotation-introducer (v4): negative where a direct quotation is about to open in running prose."""
READS = ()

QUOTE_OPENERS = {' "', '"', ' “', '“', ' «', '«', ' ‘', '‘', ' „', '„', ' 「', '「'}
COLONS = {':', ':\n', ':\n\n', '：', '：\n'}
LEAD_INS = {':', ',', ' that', ' as', ' a', ' and', ' the', '.\n', '.\n\n', ' says', ' said'}
CLOSING = {'",', '":', '.",', '",\n', '"'}
REPORT = {'said', 'says', 'say', 'saying', 'wrote', 'writes', 'reads', 'read', 'states', 'stated',
          'follows', 'noted', 'added', 'adds', 'told', 'tells', 'described', 'according',
          'statement', 'claimed', 'argued', 'explained', 'asked', 'warned'}
CODE_CHARS = set('{};=<>[]\\')


def step(carry, prefix, upstream):
    """carry: how many quote marks the document has had so far (None at a row start)."""
    toks = prefix.token_strings
    t = prefix.position
    s = toks[t]
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        quotes_before = 0
    else:
        quotes_before = carry
    carry_out = quotes_before + (1 if s in QUOTE_OPENERS or s == '"' else 0)
    before = toks[max(0, t - 12):t]
    if any(ch in CODE_CHARS for ch in ''.join(before)):
        return carry_out, 0.0
    words = [w.strip(' ,.:;"“”\'').lower() for w in toks[max(0, t - 6):t]]
    cue = any(w in REPORT for w in words)
    if s in QUOTE_OPENERS:
        prev = toks[t - 1] if t > 0 else ''
        if prev in CLOSING:
            return carry_out, 0.0
        value = -0.35
        if prev in LEAD_INS:
            value -= 0.65
        if cue:
            value -= 1.5
        if prev in LEAD_INS and cue:
            value -= 0.3
        if quotes_before == 0:
            value -= 0.3
        return carry_out, value
    if s in COLONS and cue:
        return carry_out, -1.0
    return carry_out, 0.0

programs.sol:
"""A spelling detector for sch, including sch split across word-pieces.

It predicts negative activation for sch, less for adjectival -isch and nasal
endings. It keeps a trace on the next piece. Common complete-token spellings
are suppressed. Some plain ch pieces instead get a small positive response,
larger after an umlaut. Word-specific variations are not reproduced.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# Number of letters after sch: zero, one, two, three, or four and more.
SCH = (-4.4, -3.3, -1.6, -3.3, -2.1)
SPLIT_SCH = (-8.3, -5.5, -5.3, -1.2, -0.4)
ADJECTIVAL_ISCH = (-2.7, -1.0, -1.6, 0.0, 0.0)

@lru_cache(maxsize=8192)
def familiar(word):
    return max(zipf_frequency(word, 'en'), zipf_frequency(word, 'de')) >= 4.3


def predict(t, p, old):
    i = t.rfind('sch')
    tail, scale, strengths = None, 1.0, SCH
    # Long s and OCR's f may stand for s.
    if p.endswith(('s', 'ſ', 'f')) and t.startswith('ch'):
        tail, strengths = len(t)-2, SPLIT_SCH
        if p.endswith(('is', 'iſ')):
            strengths = ADJECTIVAL_ISCH
        elif p.endswith(('ns', 'nſ')):
            scale = 0.5
        elif p.endswith(('ſ', 'f')):
            scale = 0.6 if tail < 2 else 0.15
    elif p.endswith('sc') and t.startswith('h'):
        tail, strengths = len(t)-1, SPLIT_SCH
    elif i >= 0:
        tail, before = len(t)-i-3, t[:i]
        if before.endswith('i'):
            strengths = ADJECTIVAL_ISCH
        elif before.endswith('n') or before.strip() == 'be':
            scale = 0.35
        elif i == 0 and tail == 0:
            scale = 1.5
        elif before in ('e', 'u') and tail == 0:
            scale = 1.7
    if tail is not None:
        if i >= 0 and len(t.strip()) > 4 and familiar(t.strip()):
            return 0.0
        return scale * strengths[min(tail, 4)]
    if t.startswith('ch') and len(t) <= 5 and p and p[-1].isalpha():
        return (0.5, 0.35, 0.2, 0.0)[len(t)-2] + 2.8*(p[-1] in 'äöü')
    if not t[:1].isspace() and t.endswith('ch') and len(t) <= 4:
        if t[0:1] in ('u', 'o', 'ä', 'ö', 'ü'):
            return 0.5
    last_sch = p.endswith('sch') or (
        p == 'ch' and old.endswith(('s', 'ſ', 'f')))
    if last_sch and t and t[0].isalpha():
        return {'o': -4.7, 'w': -3.1, 'e': -3.3, 'k': -3.3}.get(t[0], -1.8)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, old = '', ''
    else:
        _, p, old = carry
    t = prefix.token_strings[-1].lower()
    value = predict(t, p, old)
    return (doc, t, p), float(value)

"""A body/self-character detector, with weaker shen/sheng sound echoes.

身 alone is strong. Whole-body expressions are almost as strong; compound
words usually weaken the response, especially descriptions of appearance.
The signal also occurs on Vietnamese thân and Korean 신, and on the end
of romanized sheng. Only nearby text is remembered.
"""
import codecs
from functools import lru_cache
from pypinyin import lazy_pinyin
import regex

READS = ()
WHOLE_BODY = {'全身', '一身', '浑身', '渾身'}


def body_response(word):
    if word == '身':
        return 8.5
    if word in WHOLE_BODY:
        return 7.5
    if '健康' in word or '身影' in word:
        return 0.0
    if '身材' in word:
        return 0.4
    if word in {'健身', '瘦身', '单身', '單身'}:
        return 2.0
    if word == '身上':
        return 5.6
    if word.endswith('身') or word.startswith('自身'):
        return 4.8
    return 2.0


@lru_cache(maxsize=8192)
def sound_echo(word):
    # Chinese syllables neighboring the body character's reading, shen.
    if not regex.search(r'\p{Script=Han}', word):
        return 0.0
    syllables = lazy_pinyin(word)
    if syllables[-1] in {'shen', 'sheng'}:
        return 0.55
    if any(s in {'shen', 'sheng'} for s in syllables):
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        tail, previous = '', ''
    else:
        _, decoder, tail, previous = carry
    text = decoder.decode(prefix.token_bytes[-1])
    word = text.strip()
    joined = (tail + text).lower()
    value = 0.0
    if '身' in word:
        value = body_response(word)
    elif previous.endswith('身') and word in {'上的', '分'}:
        value = 4.5 if word == '上的' else 2.5
    elif word == 'thân':  # Vietnamese body/self
        value = 5.0
    elif word == 'sinh':  # Vietnamese life/birth
        value = 1.8
    elif word == '신':  # Korean sin, including the reading of 身
        value = 8.0 if previous == '전' else 2.1
    elif word == '생':  # Korean life/birth
        value = 0.7
    elif word.lower() == 'shen':
        value = 1.5
    elif text.lower() == 'eng' and joined.endswith('sheng'):
        value = 6.5
    elif text.lower() == 'eng' and joined.endswith('zheng'):
        value = 1.4
    elif text.lower() == 'en' and joined.endswith('shen'):
        value = 2.0
    elif word == 'ن' and tail.endswith('ش'):
        value = 2.5  # Persian shen, written شن
    elif text.lower() == 'anh' and tail.lower().endswith('th'):
        value = 2.5  # end of Vietnamese Thanh
    elif text.lower() == 'inh' and tail.lower().endswith('s'):
        value = 2.3  # end of Sinh, as in Sinhala
    elif word.lower() in {'than', 'h'}:
        # A Vietnamese context disambiguates thanh from English "than".
        vietnamese = any(c in tail.lower() for c in 'ăâđêôơưàảãạấầẩẫậ')
        if vietnamese and (word.lower() == 'than' or tail.lower().endswith('than')):
            value = 2.0
        elif word.lower() == 'h' and tail.lower().endswith('sin'):
            value = 1.8
    else:
        value = sound_echo(word)
    return (doc, decoder, (tail + text)[-64:], word), value

programs.haiku:
"""Fires on the Chinese character 身 (shēn, 'body / self') and on words built on it,
with weaker responses to a few other shēng/shēn words."""
READS = ()

BARE = {"身"}
WHOLE_BODY = {"全身", "浑身", "一身", "满身"}
SELF = {"自身", "本身", "亲身", "转身", "出身"}
WEAK = {"深", "生", "提升", "出生", "一生", "人生", "身份证", "身体", "身边", "身旁", "身价", "单身", "变身"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s in BARE:
        return None, 8.5
    if s in WHOLE_BODY:
        return None, 7.5
    if s in SELF:
        return None, 5.0
    if s in WEAK:
        return None, 1.5
    if "身" in s:
        return None, 2.0
    if s == "thân":
        return None, 4.0
    return None, 0.0

programs.sol:
"""A sparse lexical approximation, rather than a general economics detector.

Selected economy/trade spellings are positive, especially gig/sharing
and digital economy phrases; academic "economics" is near zero. Temporary
words and Chinese continuance words are negative. Separate pulses cover the characters
济/濟/済 (even outside economics), 肌 (skin/flesh), early Chinese ordinals,
and repeated middle dots. Economic compounds strengthen the Ji/sai pulse;
heart/uterine muscle compounds weaken the skin-character pulse. There is
also a small document-initial bias.
UTF-8 buffering recognizes characters split across tokens, without lookahead.
"""
import codecs

READS = ()


def lexical_value(text, previous):
    word = text.strip().lower()
    if word in {"economy", "conomy"} or (
        word == "y" and previous.endswith("conom")
    ):
        if previous in {"gig", "sharing"}:
            return 7.8
        if previous == "digital":
            return 3.8
        return 2.0
    if word in {"economies", "conomies"}:
        return 2.4
    if word == "ies" and previous.endswith("conom"):
        return 2.4
    if word == "economía":
        return 1.8
    if word == "tế" and previous == "kinh":
        return 2.2
    if word == "economics":
        return -0.1
    if word == "economic":
        return 0.55 if text.startswith(" ") else 0.0
    if word == "conomic":
        return 0.2
    if word == "conom" or word.startswith("эконом"):
        return 0.5
    if word in {"经济", "經濟"}:
        return 5.1
    if "经济" in word or "經濟" in word:
        return 2.8
    if word == "경제":
        return 3.1
    if word == "제" and previous.endswith("경"):
        return 4.8
    if word in {"济", "濟", "済"}:
        return 5.5 if previous.endswith(("经", "經", "経")) else 3.3
    if word == "贸":
        return 2.0
    if word in {"贸易", "貿易"}:
        return 0.25
    if word in {"经", "經", "経"}:
        return 0.65
    if word == "肌":
        return 2.0 if previous.endswith(("心", "子宫", "子宮", "骨骼")) else 4.8
    if "肌" in word:
        return 1.1
    if word == "temporary":
        return -0.8
    if word == "temporarily":
        return -0.65
    if word in {"临时", "臨時"}:
        return -4.5
    if word in {"暂", "暫"}:
        return -3.0
    if "暂" in word or "暫" in word:
        return -1.6
    if word in {"仍", "仍然", "依然", "依旧", "依舊"}:
        return -0.85
    if word in {"第一", "第二", "第三"}:
        return 1.6 / ("一二三".index(word[-1]) + 1)
    if len(word) >= 2 and not word.strip("·"):
        return -0.65
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    pending, previous = (b"", "") if first else carry[1:]
    raw = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(raw, "ignore", False)
    value = lexical_value(text, previous)
    if first:
        value += -0.2
        if text == "<|endoftext|>":
            value = 1.46
    carry = (document, raw[consumed:], text.strip().lower() or previous)
    return carry, value

programs.haiku:
"""layers.1.mlp.down_proj:3731, a word-level "economy" detector.

What it does, in plain terms:
- It fires on the word for economy: the Chinese 经济 (strongest, about 6), the piece 济
  (about 3.5, as in 经济 or the place name 济源), English "economies" (about 2.5) and
  "economy" (about 1.6), and weakly on "economic" (about 0.5).
- It also fires on the ordinals 第一 ("first", about 1.7) and 第二 ("second", about 0.8).
- It goes negative on "temporary" words (临时, 暂, 暂停, temporary, about -1.2) and
  "still" words (仍, 仍然, 依然).
- The first token of every document sits slightly below zero (about -0.2).
- Everything else predicts 0.

The values are read off the token's own text, so the program looks at the newest
token only (plus the document ids to find document starts). It needs no carry.
"""
READS = ()

# Chinese "economy": 经济 and compounds are strongest; 济 alone is also strong
ECON_ZH = ("经济", "經濟")
ECON_ZH_CHAR = {"济": 3.5}
# English economy words, the noun strongest
ECON_EN = {"economies": 2.5, "economy": 1.6}
ECON_EN_ADJ = {"economic": 0.5}
# ordinals 第一 ("first") and 第二 ("second")
ORDINALS = {"第一": 1.7, "第二": 0.8}
# "temporary" and "still" words push the component negative
TEMPORARY = {"临时", "暂", "暂停", "仍", "仍然", "依然", "temporary"}

DOC_START = -0.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = DOC_START  # first token of a document (or of the packed row)
    elif any(z in tok for z in ECON_ZH):
        value = 6.0
    elif tok in ECON_ZH_CHAR:
        value = ECON_ZH_CHAR[tok]
    elif word in ECON_EN:
        value = ECON_EN[word]
    elif word in ECON_EN_ADJ or "conom" in word:
        value = 0.5
    elif tok in ORDINALS:
        value = ORDINALS[tok]
    elif word in TEMPORARY:
        value = -1.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate the clearest training pattern: a one inside a numeral.

Short numeric prefixes ending in one respond most strongly after 1 or 2.
Longer prefixes, repeated ones and separators usually weaken the signal;
some leading-zero forms are negative. English eleven, tens-plus-one and
November (month eleven) provide word-form counterparts. Amplitudes are
rounded from training examples. Other activations, including occasional
large outliers, are left at a near-zero baseline.
"""

import unicodedata

READS = ()


def numeric_one(tail):
    digits = ''
    for ch in reversed(tail):
        if ch not in '0123456789':
            break
        digits = ch + digits
    before = tail[:-len(digits)] if digits else tail
    if not digits:
        if len(tail) >= 2 and tail[-1] in '.,-':
            previous = tail[-2]
            if previous in '0123456789':
                strength = 0.5 if previous in '12' else 0.10
                if previous == '0':
                    strength = 0.03
                if len(tail) >= 3 and tail[-3].isdigit():
                    strength *= 0.35
                if tail[-1] == '-':
                    strength *= 0.2
                return strength
        return -0.015

    last = digits[-1]
    if last == '0':
        if len(digits) > 1:
            return 0.10 if digits.endswith('00') else 0.025
        if before.endswith('-'):
            return -0.5
        if before.endswith('/'):
            return -0.26
        if before.endswith(('.', ',', ':')):
            return 0.06
        return -0.15

    strength = (1.26 if last == '1' else 1.10 if last == '2'
                else 0.46 if last in '34' else 0.36)
    if len(digits) > 1:
        strength *= (0.55 if len(digits) == 2 else
                     0.76 if len(digits) == 3 else 0.50)
        if len(digits) == 2 and digits[0] == '1':
            strength *= 0.32 if last in '12' else 0.60
        elif len(digits) == 2 and digits[0] in '02':
            strength *= 1.30
        if digits.endswith('11'):
            strength = max(-0.12, 0.20 - 0.12 * (len(digits) - 2))
    if before.endswith('.'):
        strength *= 0.55
    elif before.endswith((',', ':')):
        strength *= 0.78
    elif before.endswith('年') and len(digits) == 1:
        strength += 0.5
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = -0.003

    if len(token) == 1 and unicodedata.digit(token, None) == 1:
        normalized = ''.join(str(unicodedata.digit(c, c)) for c in tail)
        value = numeric_one(normalized)
    elif word.lower() in {'eleven', 'eleventh'}:
        value = 1.25 if word.islower() else 0.85
    elif token in {'ven', 'venth'} and tail.lower().endswith('ele'):
        value = 2.15 if token == 'venth' else 1.0
    elif word in {'November', 'Nov'}:
        value = 0.76 if word == 'November' else 0.41
    elif word.lstrip('-').lower() in {'one', 'first'}:
        tens = tail.rstrip(' -').lower()
        if tens.endswith('twenty'):
            value = 1.65
        elif tens.endswith(('thirty', 'forty', 'fifty', 'sixty',
                            'seventy', 'eighty', 'ninety')):
            value = 0.5
    elif token == '一' and tail.endswith(tuple('一二三四五六七八九')):
        value = 0.8

    return (doc, (tail + token)[-64:]), float(value)

"""Approximate document-opening signal from spelling and word classes.

Honorific, calendar and reference abbreviations receive negative estimates;
wh-words and deictic words receive positive estimates. Defaults use script,
case, spacing and punctuation. Values are fitted class means, not a token
lookup table. An initial run of identical tokens retains its opening value;
after that, the prediction is zero. Token-specific variation is not modeled.
"""
import calendar
import regex as re
import unicodedata

READS = ()
TITLES = set('Mr Mrs Ms Dr Prof Rev Fr St Hon Esq Gov Sen Rep'.split())
REFERENCES = set(
    'Fig FIG Eq Eqn No Nos Vol Ref Ch Chap Sec Ex Int Ext Dep Dept Ed '
    'pp etc vs Inc Ltd Co Corp Mt'.split()
)
DATES = set(calendar.month_abbr[1:]) | set(calendar.day_abbr)
DATES.discard('May')  # This is a complete month name, not a shortening.
QUESTIONS = set('What Who Where When Why Which Whose Whom'.split())
DEICTICS = set('Today Tomorrow Yesterday Here There Now'.split())
DEMONSTRATIVES = set('This That These Those'.split())
HEADINGS = set('Question Answer Name Title user assistant system'.split())


def opening_value(token):
    word = token.strip()
    spaced = token.startswith(" ")
    if word in TITLES:
        return (-8.39 if spaced else -11.53)
    if word in REFERENCES:
        return (-9.47 if spaced else -6.54)
    if word in DATES:
        return (-5.96 if spaced else -7.38)
    if re.fullmatch(r'[BCDFGHJKLMNPQRSTVWXZ][bcdfghjklmnpqrstvwxz]{1,2}', word):
        return (-4.05 if spaced else -2.68)
    if word in QUESTIONS:
        return (2.48 if spaced else 4.83)
    if word in DEICTICS:
        return (1.92 if spaced else 5.68)
    if word in DEMONSTRATIVES:
        return (-0.81 if spaced else 1.55)
    if word in HEADINGS:
        return (0.22 if spaced else 4.21)
    if word in {'www', 'http', 'https'}:
        return (-1.54 if spaced else -3.98)
    if word == '\\t':
        return 8.21
    if word == '.\\':
        return -11.75
    if word and set(word) <= {'·', '^'} and len(word) >= 2:
        return -6.51
    if word.isdigit():
        return 0.26
    if word.startswith('<|') or not word:
        return -0.06
    if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return (-1.99 if spaced else -1.25)
    if any('THAI' in unicodedata.name(c, '') for c in word):
        return -4.19
    if not any(c.isalnum() for c in word):
        return (-0.21 if spaced else -0.08)
    if re.search(r'\p{Script=Han}', word):
        return (0.28 if spaced else -0.15)
    if word.isascii() and word.isalpha():
        if word.islower():
            return (0.45 if spaced else 1.73) if len(word) == 1 else (-0.41 if spaced else 1.45)
        if word.isupper():
            return (-0.71 if spaced else -0.37) if len(word) == 1 else (-0.16 if spaced else 1.21)
        if word.istitle():
            return (-0.2 if spaced else 1.15)
    return (-1.04 if spaced else -0.13) 


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        text = prefix.token_strings[-1]
        value = opening_value(text)
        return (doc, token, value), value
    # A homogeneous opening can last for several identical tokens.
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

"""Approximate the response at the end of an ASCII digit sequence.

Ordinarily predict zero. At recognized endings, use capped log-number
magnitude and simple context rules. Punctuation is more negative in
number-heavy text; fractions and year-like values are weaker. Larger
ordinals and Chinese count markers are negative, while percentages,
months and hours are positive. Document boundaries reset the state.
"""
from collections import deque
from math import log10

READS = ()
COUNT_MARKERS = frozenset("个名人件辆条位家台项户种所只批次回集章节页号型岁歲元万多")


def strength(value, threshold, cap):
    return min(cap, max(0.0, log10(max(value, threshold) / threshold)))


def ending(token, number, before, start, density, recent):
    value = min(int(number), 10000)
    # A zero-padded identifier still behaves like a multi-digit number.
    if len(number) >= 3 and number.startswith('0'):
        value = max(value, 100)
    year = len(number) == 4 and 1800 <= value <= 2100
    modern_year = year and value >= 1900
    decimal = before == '.'
    space = before.isspace()
    density -= .2
    recent -= .2

    if token == '.':
        h = strength(value, 8, 1.3)
        gain = (-1.748 - 3.656 * density + .655 * year
                + .552 * modern_year + 1.735 * decimal)
        at_start = start == 0
        return .019 + h * (gain - 1.176 * at_start) - 1.619 * at_start
    if token == ',':
        h = strength(value, 5, 1.3)
        gain = (-.529 - 2.040 * recent + .605 * year
                + .544 * decimal - .690 * (before == ','))
        return .012 + h * gain
    if token == ' ':
        h = strength(value, 12, .7)
        return -.038 + h * (-.559 - 2.096 * recent - 1.185 * space
                            + .375 * modern_year)
    if token == ':':
        return .077 - strength(value, 40, .7) * (1.398 + .791 * (start < 40))
    if token in ('th', 'st', 'nd', 'rd'):
        return .348 - 8.403 * strength(value, 15, .7)
    if token.startswith('\t') and token.isspace():
        response = .055 - strength(value, 5, 1.6) * (.343 + 1.654 * density)
        return response / (1 + .35 * token.count(' '))
    if token in (']', ' ]'):
        return -.044 - strength(value, 5, 1) * (.763 + .416 * density)
    if token in ('-', '–', '—'):
        return -.006 + strength(value, 15, .7) * (
            -1.079 + 1.114 * year + 1.534 * (len(number) > 4))
    if token == '/':
        return .044 + strength(value, 15, .7) * (-1.091 - space + .560 * year)
    if token == '年':
        return .371 + strength(value, 8, .7) * (-3.678 + 2.172 * year)
    if token.strip().startswith('%'):
        return (.041 + .361 * max(0, min(value, 100) - 30) / 70
                + 1.418 * (len(number) >= 3))
    if token == ')':
        return .013 - .477 * strength(value, 20, .5)
    unit = token.strip().removesuffix('s')
    if unit == 'month':
        return -.009 + 4.893 * strength(value, 10, 1.3)
    if unit == 'hour':
        return .135 + 1.710 * strength(value, 20, 2)
    if unit == 'year':
        return .166 - 1.910 * strength(value, 15, .5)
    # Common Chinese markers for counts, amounts and numbered items.
    if token in COUNT_MARKERS:
        return -.583 - 3.853 * strength(value, 15, .5)
    if token == '路':  # A numbered route.
        return -3 * log10(value + 1)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, number='', before='', previous='', start=0,
                     count=0, digits=0, recent=deque(maxlen=32))
    token = prefix.token_strings[-1]
    digit = token.isascii() and token.isdigit()
    prediction = 0.0
    if digit:
        if not carry['number']:
            carry['before'] = carry['previous']
            carry['start'] = carry['count']
        carry['number'] += token
    else:
        if carry['number']:
            prediction = ending(
                token, carry['number'], carry['before'], carry['start'],
                carry['digits'] / max(1, carry['count']),
                sum(carry['recent']) / max(1, len(carry['recent'])))
        carry['number'] = ''
    carry['previous'] = token
    carry['count'] += 1
    carry['digits'] += token.isdigit()
    carry['recent'].append(token.isdigit())
    return carry, float(prediction)

"""An empty-context pulse, mostly negative.

The pulse lasts while a document contains only repeats of its first token.
Its size depends on the token's readable form: punctuation and indentation,
import declarations, and whether a word looks like a frequent sentence opener
or an unspaced fragment. Once distinct context arrives, predict zero.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()

AUXILIARIES = frozenset('is are am be been being was were have has had '
                        'do does did can could will would should must may might'.split())
PRONOUNS = frozenset('I you he she it we they me him her us them my your our'.split())


@lru_cache(maxsize=32768)
def initial_value(text):
    word = text.strip()
    spaced = text.startswith(' ')
    if text.startswith('<|'):
        return -0.93
    if not word:
        if '\t' in text:
            return -2.0
        if '\n' in text or '\r' in text:
            return -1.05 if spaced or text.count('\n') > 1 else -1.30
        if text == ' ':
            return 0.0
        return -1.1 if len(text) == 2 else -1.5
    if word.isdecimal():
        return -1.12
    # Recognizable import/package syntax has a different initial sign.
    if not spaced:
        if word == 'import':
            return 1.9
        if word == 'from':
            return 0.9
        if word == '#include':
            return 0.35
        if word in {'using', 'const'}:
            return 0.0
        if word == 'package':
            return -0.76
    if not any(ch.isalnum() for ch in word):
        if '"""' in word or "'''" in word:
            return -4.4
        if '\\"' in word:
            return -3.8
        if '\n' in text:
            return -0.6 if text.count('\n') > 1 else -1.35
        if set(word) == {'#'}:
            return -0.5
        if set(word) == {'^'} and len(word) > 1:
            return -5.0
        if word in {'.', '-'}:
            return -0.8 if spaced and word == '-' else 0.0
        if word in {',', '，', '、', '?', '？'}:
            return -0.8
        if word in {':', '=', '/', '_'}:
            return -0.35
        if word in {'(', '[', '（', '【', '<'}:
            return -0.3 if spaced else -0.8
        if word in {')', ']', '}', '）', '】'}:
            return -0.65
        if word in {'"', "'", '“', '”', '‘', '’'}:
            return -0.15 if spaced else -1.2
        if word in {'*', '**'}:
            return -2.0
        if word == '%':
            return -3.6
        return -1.2
    if word.isascii() and word.isalpha():
        if word.lower() == 'the':
            return -1.18 if spaced else -0.72
        if spaced and word == 'a':
            return -1.68
        if spaced and word in AUXILIARIES:
            return -0.65
        if word in PRONOUNS:
            return -1.0
        frequency = zipf_frequency(word, 'en')
        if spaced:
            return (-1.55 - 0.2 * max(3.0 - frequency, 0.0)
                    + 0.35 * max(frequency - 5.5, 0.0))
        if len(word) == 1:
            return -1.2 if frequency >= 7 else -2.2
        if word[0].isupper():
            return min(-0.6, -2.25 + 0.7 * max(frequency - 5.2, 0.0))
        return -2.2 + 0.3 * max(frequency - 5.0, 0.0)
    if regex.search(r'\p{Script=Han}', word):
        return -1.25
    return -1.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        initial = True
    elif carry[1] == token and carry[2]:
        value = carry[3]
        initial = True
    else:
        value = 0.0
        initial = False
    return (doc, token, initial, value), value

"""A GitHub-address detector with a document-initial shape correction.

Completing github.com in a URL gives a strong positive pulse; bare Go
imports and checkout/API paths give smaller ones, as does java.net.
At a document's beginning, dot-prefixed fragments instead give a large
negative pulse.  Other initial
tokens are approximated by their punctuation, script and capitalization.
The initial number prefix '12' has a separate positive pulse on its '2'.
"""
import regex

READS = ()


def initial_value(token):
    text = token.strip()
    if token == ' .':
        return -8.0
    if text and set(text) == {'·'}:
        return -6.28 if len(text) > 1 else -0.55
    if text.startswith('.'):
        if text == '.':
            if token.endswith('\n\n'):
                return -0.28
            return -1.3 if token.endswith('\n') else 0.49
        if set(text) == {'.'}:
            return 1.2
        return -4.8
    if not text:
        return -0.38
    if text.isascii() and text.isdigit():
        return 0.06
    if text.startswith('#'):
        return -0.87
    if text.startswith('/'):
        return -1.9 if any(c.isalpha() for c in text) else -0.5
    if regex.search(r'\p{Script=Han}', text):
        return -0.31
    if text.isascii() and text[0].isupper():
        return -0.28 if token.startswith(' ') else -0.44
    if text.isascii() and text[0].islower():
        return -0.12
    return -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, age, first, uniform = '', 0, token, True
    else:
        _, tail, age, first, uniform = carry
        uniform = uniform and token == first

    value = -0.002
    if uniform:
        value = initial_value(token)
    elif age == 1 and tail == '1' and token == '2':
        value = 6.63
    elif token == '.com':
        if tail.endswith('.github'):
            value = 0.34
        elif tail.lower().endswith('githubusercontent'):
            value = 4.0
        elif tail.lower().endswith('github'):
            if tail.endswith('https://github'):
                value = 4.4
            elif tail.endswith('://github'):
                value = 3.7
            elif tail.endswith('\\"github'):
                value = 3.25
            elif tail.endswith('"github'):
                value = 4.0
            else:
                value = 3.0
        else:
            value = 0.02
    elif token == '/repos' and tail.endswith('api.github.com'):
        value = 2.0
    elif token == '.net' and tail.endswith('java'):
        value = 0.8
    elif token.lower() == '/github':
        value = 1.1
    elif token.lower() == 'ithub' and tail.lower().endswith('-g'):
        value = 0.6

    return (doc, (tail + token)[-60:], age + 1, first, uniform), value

"""Discourse links, rather than ordinary list commas.

Predict a negative response when a comma closes a consequence, contrast,
or introductory phrase. Some non-Latin connectives and demonstratives carry
the response on the word itself. Chinese coordination and a few layout openings are positive.
This deliberately omits the many small, word-specific background responses.
"""
import re

READS = ()
RESULT = set('thus hence therefore consequently accordingly'.split())
CONTRAST = set('however instead nevertheless nonetheless unfortunately '
               'fortunately still though yet'.split())
ASIDE = set('clearly obviously indeed also well similarly alternatively '
            'again actually overall specifically'.split())
STRONG_PHRASES = (
    'in fact', 'in reality', 'in this case', 'in that case',
    'for this reason', 'as a result', 'as such', 'of course',
    'in my opinion', 'in this way', 'this way',
)
INTRO = re.compile(
    r'(?:^|[.!?\n])\s*(?:In|On|At|For|By|From|With|As|After|Before)'
    r'\b[^,.!?\n]{0,55}$')
SENTENCE_END = re.compile(r'[.!?。！？][\s”’"\'」』）)]*$')
CLAUSE_END = re.compile(r'[,;:，；：][\s”’"\'」』）)]*$')
CN_RESULT = ('所以', '因此', '那么', '那麼')
CN_LINKS = ('但是', '因为', '因為', '同时', '同時', '其中', '如今')
DIRECT_LINKS = set(CN_RESULT + ('同时', '同時', '另外', '此外',
                              '不过', '不過', '其实', '其實'))
JP_LINKS = {'また', 'だから', 'そのため', 'ですから', 'ですので'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous, strength = '', '', 0.0
    else:
        _, text, previous, strength = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value, following = 0.0, 0.0
    sentence_start = bool(SENTENCE_END.search(text))
    clause_start = sentence_start or bool(CLAUSE_END.search(text))
    if token.rstrip() in (',', '，'):
        match = re.search(r'([^\W\d_]+)$', text)
        if INTRO.search(text):
            value = -.12
        if match:
            link = match[1]
            lower = link.lower()
            if lower in RESULT:
                value = -.70
            elif lower in CONTRAST:
                value = -.32
            elif lower in ASIDE:
                value = -.23
            elif lower in ('and', 'or', 'but'):
                value = -.95 if link[0].isupper() else -.50
            elif lower == 'so':
                value = -1.35 if link[0].isupper() else -.30
            elif lower in ('now', 'then', 'today', 'meanwhile'):
                value = -.75 if link[0].isupper() else -.30
            elif lower in ('that', 'which', 'who'):
                value = -.35
            elif lower in ('однако', 'поэтому', 'alors', 'ahora', 'porém'):
                value = -1.0
        if text.lower().endswith(STRONG_PHRASES):
            value = -.60
        if text.endswith(CN_RESULT):
            value = -1.40
        elif text.endswith(CN_LINKS):
            value = -1.0
        if '\n' in token:
            value *= .65
        following = value
    elif token == ' to' and (strength < -.6 or previous.strip() in ('So', 'Thus')):
        value = -.55
    elif token == ' what' and strength < -1.0:
        value = -.70
    elif word.startswith('而') and clause_start:
        value = -1.35 if sentence_start else -.65
    elif word in ('与', '與', '和') and clause_start:
        value = .62
    elif word == '或是':
        value = 1.0
    elif word in DIRECT_LINKS:
        value = -.30
    elif word in JP_LINKS or word in ('据悉', '據悉', '至于', '至於'):
        value = -.95
    elif word == 'なお':
        value = -1.8
    elif word in ('でも', 'しかし', 'その') and clause_start:
        value = -.42
    elif word.lower() in ('однако', 'поэтому', 'так'):
        value = -.48
    elif word in ('그', '그러', '그러나', '그리고', '따라서'):
        value = -.55
    elif token == '\n\n' and text.endswith('</think>'):
        value = .39
    elif token == '</think>':
        value = -.13
    elif token == '<|im_start|>' and previous == '<|endoftext|>':
        value = .375
