          and re.search(r'/[^\n]*:\n$', text)):
        value = .45
    elif token == '](':
        value = .48 if re.search(r'\[\d+$', text) else .12
    return (doc, (text + token)[-200:], token, following), value

"""Separators inside parentheses and other bracketed groups.

Track literal unmatched ASCII brackets, including those in quoted text.
Parenthetical context grows over the first few tokens and fades over long
spans; nesting and square/curly brackets add smaller bonuses. Commas,
semicolons and inner closing brackets respond most strongly. Other
punctuation and English function words respond more weakly; ordinary
content words are nearly zero. This is not a full code or string parser.
"""
import math

READS = ()

CONNECTORS = set('''
and or but nor yet so for because although while if when since as than that
whether until unless whereas though before after
'''.split())
FUNCTION_WORDS = set('''
of in to from with at by on into about over under between through during per
without within against among is are was were be been being am have has had
do does did can could may might shall should will would must not a an the
this that these those all any each every some no one such other it they he
she we you i its their his her our your my
'''.split())


def response(s, previous):
