    t = s.strip()
    if not t:
        return -0.01, 0.22
    if any(c in t for c in '([{'):
        return -0.10, 0.21
    if not any(c.isalnum() for c in t):
        if ',' in t:
            return 0.04, 1.05
        if ';' in t:
            return -0.05, 1.05
        if ':' in t:
            if any(c in t for c in '\'"'):
                return -0.09, 0.44
            return 0.01, 0.23
        if any(c in t for c in '\'"`'):
            if '`' in t:
