        return 0.0, 0.52
    if all(c in '-–—' for c in t):
        return -0.02, 0.30
    has_operator = any(c in t for c in '+-=*/<>|&∧⇒')
    if has_operator and not any(c.isalpha() for c in t):
        return (0.08, 0.67) if t in ('&&', '||') else (-0.02, 0.29)
    if any(ord(c) > 128 for c in t):
        return -0.01, 0.10
    if any(c.isalpha() for c in t):
        return (-0.02 if t.startswith('.') else 0.0), 0.02
    return 0.0, 0.35


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        stacks, previous = [[], [], []], ''
    else:
        _, stacks, previous = carry
    s = prefix.token_strings[-1]
    position = prefix.position
    for char in s:
        if char in '([{':
            stacks['([{'.index(char)].append(position)
        elif char in ')]}':
            stack = stacks[')]}'.index(char)]
            if stack:
                stack.pop()
    round_depth, square_depth, curly_depth = map(len, stacks)
    enclosure = 0.0
    if round_depth:
        age = position - stacks[0][-1]
        maturity = 1.0 - math.exp(-age / 4.0)
        enclosure = 1.8 * maturity * math.exp(-age / 32.0)
    enclosure += 0.30 * (round_depth > 1)
    enclosure += 0.50 * min(square_depth, 2)
    enclosure += 0.20 * min(curly_depth, 2)
    baseline, gain = response(s, previous)
    return (doc, stacks, s), float(baseline + gain * enclosure)

"""Approximate a BAR spelling-fragment response, not a pub detector.

Short BAR tokens and B | AR splits get positive values; longer words
are weaker. A following alphabetic fragment gets a smaller response.
BUN/BUND, BOON/BUMP splits, and BARRIER have negative responses.
There are also rules for Cyrillic BAR, Korean BA, Japanese BAA, and
Chinese column/railing characters. Other tokens get a small baseline,
negative at the start of a document. Word-specific context is omitted.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32000)
def spelling(text):
    return anyascii(text).lower()


def response(raw, previous, previous_raw):
    text = spelling(raw)
    word = text.strip()
    if raw.strip() == 'бар':
        return 8.0
    if raw.strip() == '바':
        return 5.5
    if raw.strip() in ('栏', '欄'):
        return 2.5
    if raw.startswith('ー') and previous_raw.rstrip().endswith('バ'):
        return 4.0
    if word.startswith('barrier'):
        return -0.5
    if word in ('barred', 'barring'):
        return 5.0
    if word.startswith('barbar'):
        return 4.0
    if word.startswith('bar'):
        if len(word) <= 4:
            return 3.7
        return 1.1 if len(word) <= 7 else 0.2
    if word.endswith('bar'):
        return 3.5 if len(word) <= 4 else 1.3
    if previous.endswith('b') and text.startswith('ar'):
        return 6.3 if len(text) <= 4 else 1.5
    if previous.endswith('b'):
        if text.startswith('un'):
            return -3.0 if len(text) <= 3 else -1.0
        if text.startswith('oon'):
            return -2.4
        if text.startswith('ump'):
            return -1.3
    if word == 'bun':
        return -2.3
    if previous.endswith('bar') and text.isalpha():
        return 1.3
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, previous_raw = ('', '') if start else carry[1:]
    raw = prefix.token_strings[-1]
    value = response(raw, previous, previous_raw)
    if start and value == 0.003:
        value = -0.24
    return (doc, spelling(raw), raw), value

