"""Layer 1, MLP down_proj, component 3742: a sparse detector for a few word endings.

Most of the time this component is silent (its activation is near 0). It fires on a
handful of token families, and its sign depends on which family:

- the role word "assistant" right after "<|im_start|>" (start of a chat reply): a steady
  positive value, about +0.6;
- a carriage return "\\r": a negative value, about -0.3;
- the "-han / -stan" family of name and place endings (Khan, Rahman, Hassan, Afghanistan,
  Persian ان, Russian стан): a strong negative value, about -1.1;
- the "-ania / -anie / -ovan / -van / -jan / -lan" family (Polish and Slavic noun endings
  and names): a moderate positive value, about +0.5.

Everything else predicts 0. The values are the family means measured on training text,
so the program captures the large, consistent events but not the many weak, context-
dependent ones.
"""

READS = ()

ASSISTANT_TOKEN = "assistant"
TURN_START = "<|im_start|>"
CARRIAGE_RETURN = "\r"
NAME_ENDINGS_NEG = {"han", "ahan", "stan", "istan", "istani", "Khan", "Rahman", "Hassan", "Hasan",
                    "aan", "ان", "وان", "стан"}
NOUN_ENDINGS_POS = {"ania", "anie", "aniu", "anych", "ovan", "van", "jan", "lan", "zan", "ony"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token == ASSISTANT_TOKEN and previous == TURN_START:
        return carry, 0.63
    if prefix.token_strings[-1] == CARRIAGE_RETURN:
        return carry, -0.31
    if token in NAME_ENDINGS_NEG:
        return carry, -1.13
    if token in NOUN_ENDINGS_POS:
        return carry, 0.46
    return carry, 0.0

