import re

READS = ()


def response(tail, token):
    if token == ' line' and tail.endswith('\",'):
        return -4.1 if tail.endswith('.py\",') else -1.45
    if token == ':' and tail == 'Title':
        return 5.23
    if token == 'Title' and not tail:
        return -1.01
