    if token == ' optional' and tail.endswith(','):
        match = re.search(r'([:(])\s*[\w.\[\] ]{1,55},$', tail)
        if match:
            return -2.0 if match[1] == ':' else -1.4
    if token == 'default' and tail.endswith('('):
        if 'None' in tail[-30:]:
            return -1.35
    # Code-golf headings end in a language name and a byte count.
    if token == ' bytes' and re.search(r',\s*\d+$', tail):
        return -2.35
    if token == 'udos' and re.search(r'Followers:\s*\d+\s+K$', tail):
        return -1.25
    if token == ' file' and tail.endswith('Additional'):
        return -0.9
    if token == ' question' and tail.endswith('Rate this'):
        return -2.25
    if token == ' ' and re.search(
        r'(?:^|\n)(Mathematics|Math),$', tail
    ):
        return -4.5
    if token == 'Greetings' and tail.endswith('Hints ('):
        return -5.55
    if token in (' Judge', ' Judges'):
        if tail.endswith((' Law', ' Circuit', ' District')):
            return -1.2 if token == ' Judge' else -1.9
    # Other conventional web-page labels and rendered notebook output.
    if token == 'ularity' and tail.endswith('Difficulty Pop'):
        return -4.3
    if token == 'png' and tail.endswith('!['):
        return -1.15
    if token == ' Solution' and tail.endswith('Detailed'):
        return -0.8
    if token == 'Total' and re.search(r'Points \d+ \[$', tail):
        return -0.6
    if token == ' PASS' and re.search(r'(?:^|\n) *---$', tail):
        return 0.75 if tail.endswith('    ---') else 0.32
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(tail, token)
    return (doc, (tail + token)[-160:]), value

