import functools
import wordnet

READS = ()
OWNERS = {
    'my': 1.0, 'your': 1.0, 'his': 0.85, 'her': 1.0,
    'our': 1.0, 'their': 0.8, 'its': 0.12, "'s": 0.28, '’s': 0.28,
