@functools.lru_cache(maxsize=8192)
def word_response(token):
    word = token.strip().lower()
    classes = wordnet.categories(word)
    plural = word.endswith('s') or word in {
        'children', 'people', 'men', 'women', 'feet', 'teeth'
    }
    if wordnet.is_a(word, 'relative'):
        if 'noun.act' in classes:
            return -1.04
        if plural:
            return -2.03
        if wordnet.is_a(word, 'spouse'):
            return -2.27
        return -3.03
    if wordnet.is_a(word, 'group'):
        if wordnet.is_a(word, 'district'):
            if wordnet.is_a(word, 'geographical area'):
                return -5.08
            return -2.19
        if wordnet.is_a(word, 'building'):
            if wordnet.is_a(word, 'organization'):
                return -2.73
            return -0.38
        if plural:
            if wordnet.is_a(word, 'institution'):
                return 1.00
            return -0.22
        if wordnet.is_a(word, 'container'):
            return -2.00
        return -0.76
    if plural and 'noun.cognition' in classes:
        return 0.53
    if 'noun.person' in classes:
        if 'noun.attribute' in classes:
            if 'noun.communication' in classes:
                return -0.13
            return 0.58
        if wordnet.is_a(word, 'friend'):
            return -1.51
        return -0.61
    if 'noun.artifact' in classes:
        if 'noun.act' in classes:
            return -0.09
        return -0.53
    if wordnet.is_a(word, 'situation'):
        return -1.06
    return -0.06

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:
        owner, age = 0.0, 0
    else:
        owner, age, _ = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if (owner and 1 <= age <= 5 and word not in STOP
            and token[:1].isspace() and word.isalpha()):
        value = owner * DISTANCE[age - 1] * word_response(token)
    if owner and 2 <= age <= 5 and word in {"'s", '’s'}:
        value = -2.2 * owner * DISTANCE[age - 2]
    if word in OWNERS:
        owner, age = OWNERS[word], 1
    elif word in STOP or (token.strip() and not any(c.isalnum() for c in token)):
        owner, age = 0.0, 0
    else:
        age += 1
    return (owner, age, doc), value

"""Detect the spelling/romanization 'us' (or 'uz') at the current token.

Short suffix tokens give the largest response, especially Latin-like -inus,
-anus and -itus endings. Whole words and long continuations give less. English
frequency and relative French frequency adjust the current word fragment's
response. Short s-like syllables after u, palatal s letters and Polish sz
receive additional boosts. Romanization also lets the same rule see some non-Latin spellings.
Two collateral responses are an en dash and a document-initial 'Title:' header.
The carry contains only the previous token, word fragment and document position.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# Shape: syllable strength multiplier, English frequency, French excess frequency.
SHAPES = {
    'bare': (1.365, -0.329, -0.445),
    'doubled': (1.026, -0.403, -0.326),
    'consonant': (0.686, -0.585, -0.066),
    'vowel': (0.513, -0.281, -0.176),
    'suffix': (0.616, -0.371, -0.057),
    'word': (0.221, -0.085, -0.041),
    'cross_unicode': (0.286, 1.583, 0.875),
    'cross_ascii': (0.587, 1.209, 0.169),
    'inside': (0.040, 0.007, 0.012),
}

@lru_cache(50000)
def roman(text):
    return anyascii(text).lower()

@lru_cache(50000)
def frequencies(word):
    en = zipf_frequency(word, 'en')
    fr = zipf_frequency(word, 'fr')
    return max(0., en - 3.), max(0., fr - en)


def response(previous, token, word):
    text = roman(token)
    prior = roman(previous) if token and not token[0].isspace() else ''
    match = re.search(r'[a-z]+$', prior)
    prior = match.group() if match else ''
    boundary = len(prior)
    joined = prior + text
    events = [m for m in re.finditer('u[sz]', joined)
              if m.start() + 1 >= boundary]
    if not events:
        return 0.
    u = events[-1].start()
    stem = joined[:u]
    last = stem[-1:]
    tail = joined[u + 2:]
    if u + 1 == boundary and len(text) <= 3:
        shape = ('cross_ascii' if (previous + token).isascii()
                 else 'cross_unicode')
    elif text == 'us' and not token[0].isspace():
        shape = 'bare'
    elif u == boundary and len(text) <= 4 and not token[0].isspace():
        if tail.startswith(('s', 'z')):
            shape = 'doubled'
        elif tail and tail[0] not in 'aeiou':
            shape = 'consonant'
        else:
            shape = 'vowel'
    elif not tail and not token[0].isspace() and len(text) <= 6:
        shape = 'suffix'
    else:
        shape = 'inside' if tail else 'word'

    strength = 1.475
    if not stem:
        strength -= 0.498
    if last and last in 'aeouy':
        strength -= 1.073
    # The stem's last letter, and familiar Latin-like endings.
    strength += {'i': .582, 'n': 1.479, 'm': .222,
                 'l': -.106, 'r': -.050, 't': .543}.get(last, 0.)
    for ending, extra in (('in', 1.639), ('an', 1.543), ('on', .819),
                          ('it', 1.602), ('at', -.982)):
        if stem.endswith(ending):
            strength += extra
    scale, common, french = SHAPES[shape]
    en, fr = frequencies(word.lower())
    value = scale * strength + common * en + french * fr
    cross = not token[0].isspace() and roman(previous).endswith('u')
    if cross and text in ('s', 'ss', 'sz', 'su', 'seu', 'si', 'sy', 'st'):
        value += 0.94
    if cross and any(c in token for c in 'šśșş'):
        value += 2.15
    if text.startswith('usz'):
        value += 2.82
    return max(-1., min(9., value))


