    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word, position = '', '', 0
    else:
        _, previous, word, position = carry
    match = re.search(r'[^\W\d_]+$', word + token)
    word = match.group()[-60:] if match else ''
    value = response(previous, token, word)
    if token.strip() == '–':
        value = 0.38
    if token == ':' and previous == 'Title' and position == 1:
        value = 5.35
    return (doc, token, word, position + 1), value

