    elif any(ch in word for ch in '为為爲'):
        w = _SIMPLIFY.convert(word)
        before = _SIMPLIFY.convert(recent)
        if w == '为了':
            value = 5.5 if before.endswith('是') else 1.9
        elif w == '是为了':
            value = 5.0
        elif w in ('为你', '为您', '为其', '为我们', '为之', '为人'):
            value = 0.0 if ASSIGNMENT.search(before) else 4.3
        elif w in ('为大家', '为企业', '为此', '华为'):
            value = 2.1
        elif w == '为自己':
            value = 2.9
        elif w in ('只为', '也为', '尤为', '专门为'):
            value = 4.2
        elif w == '更为':
            value = -2.1 if before.endswith('变') else 3.4
        elif w in ('极为', '最为', '颇为'):
            value = 1.5
        elif w == '时间为':
            value = -2.4
        elif w in ('约为', '率为', '分别为'):
            value = -0.9
        elif w == '为什么':
            value = 0.5
        elif w == '成为':
            value = 0.3
    elif word.lower() == 'wei':
        value = 2.7
    elif word == '··':
        value = 1.06
    elif word == '是':
        value = -0.25
    elif word == '被':
        value = 0.4
    elif word == '值得':
        value = 0.9
    return (doc, (recent + token)[-64:]), value

"""Adverbial modifiers: degree, restriction, repetition, frequency and time.

The strongest responses are to 'only', superlative 'most', and 'first'.
Grammatical neighbors distinguish adverbial 'only' from 'the only', and
clause-internal 'then/also' from connective uses. Other adverbs get smaller
responses, including common translations and split-word completions.
The isolated first token has a separate, usually negative baseline.
"""
from functools import lru_cache
import regex
import wordnet

READS = ()


def words(s):
    return frozenset(s.split())


FOCUS = words('merely simply solely exclusively')
INTENSITY = words('very too quite really pretty absolutely completely '
                  'entirely totally utterly extremely almost nearly')
HABITUAL = words('always usually often normally')
FREQUENCY = words('generally typically '
                  'frequently commonly regularly sometimes occasionally '
                  'rarely seldom')
TIME = words('already still again soon recently currently previously '
             'formerly finally eventually initially originally immediately once')
MILD_DEGREE = words('especially particularly relatively slightly rather '
                   'equally exactly precisely truly mostly primarily')
CONNECTIVE = words('however therefore thus otherwise nevertheless '
                   'nonetheless indeed also even instead')
SEQUENCE = words('second third next last since earlier later today '
                 'yesterday tomorrow early late')
AUXILIARY = words('am is are was were be been being have has had can could '
                  'may might must shall should will would do does did')
DETERMINER = words('a an the this that these those my your his her its our their')
POSSESSIVE = words('my your his her its our their')
ARTICLES = words('a an the')
JOINER = words('and or but if than as')
PRONOUN = words('i you he she it we they')
REFLEXIVE = words('myself yourself himself herself itself ourselves yourselves '
                  'themselves')
FOREIGN_ONLY = words('nur seulement только лишь somente apenas')
FOREIGN_DEGREE = words('más mais plus più mehr daha более очень muy très '
                       'sehr molto muito ganz 더 好 很 更 更加 '
                       '非常 十分 比较 最')
FOREIGN_TIME = words('noch encore ainda уже déjà già bereits schon siempre '
                     'sempre toujours immer wieder ещё еще nun erst')
FOREIGN_ALSO = words('auch aussi también também anche également также 又 再')


@lru_cache(maxsize=32768)
def lexical(s):
    if s == 'just':
        return 0.9
    if s == 'even':
        return 0.75
    if s in FOCUS:
        return 0.65
    if s in INTENSITY:
        return 0.8
    if s in HABITUAL:
        return 0.95
    if s in FREQUENCY:
        return 0.6
    if s in TIME or s in FOREIGN_TIME:
        return 0.8
    if s in FOREIGN_ONLY:
        return 1.2
    if s in FOREIGN_DEGREE:
        return 0.65
    if s in MILD_DEGREE or s in CONNECTIVE or s in FOREIGN_ALSO:
        return 0.5
    if s in {'before', 'after', 'until'}:
        return 0.5
    if s in SEQUENCE:
        return 0.3
    if s in {'never', 'ever', 'either', 'least'}:
        return 0.6
    if s in {'less', 'both', 'neither', 'same'} or s in REFLEXIVE:
        return 0.23
    if s in {'best', 'worst'}:
        return 0.28
    if s in {'twice', 'thrice', 'times'}:
        return 0.45
    if s in {'now', 'then', 'yet'}:
        return 0.4
    if s in {'después', 'setelah', 'после', 'après', 'dopo'}:
        return 0.5
    if s in {'first', 'only', 'most', 'more'}:
        return 0.6  # refined by the grammatical rules below
    if not s.isalpha():
        return 0.0
    pos = wordnet.parts_of_speech(s)
    if 'adverb' in pos and s.endswith('ly'):
        return 0.35
    if 'adjective' in pos and s.endswith('est'):
        return 0.32
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    previous, tail = ('', '') if new_doc else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    # Reassemble alphabetic subwords, but not spaceless Chinese sentences.
    if regex.fullmatch(r'[\p{Latin}\p{Cyrillic}]+', s):
        joined = (tail + s)[-60:] if not token[:1].isspace() else s
        tail = joined
    else:
        joined, tail = s, ''
    value = lexical(s)
    if joined != s and lexical(joined) > 0:
        s = joined
        value = lexical(s)
    sentence_start = not previous or previous[-1:] in '.!?'
    preverbal = previous in AUXILIARY or previous in PRONOUN
    if s == 'first':
        value = 0.88
    elif s == 'most':
        if previous == 'the' or previous in POSSESSIVE or previous == "'s":
            value = 1.75
        else:
            value = 1.05 if preverbal or previous == 'and' else 0.5
    elif s == 'only':
        if previous in ARTICLES or previous in POSSESSIVE:
            value = 0.35
        elif previous == 'not':
            value = 0.45
        else:
            value = 1.7 if preverbal else 1.4
    elif s == 'more':
        if previous in {'or', 'one', 'two', 'three', 'no', 'any'}:
            value = 0.1
        else:
            value = 1.0 if previous in DETERMINER else 0.65
    elif s == 'then':
        if preverbal:
            value = 1.25
        elif previous in JOINER or not previous.isalpha():
            value = 0.0
        else:
            pos = wordnet.parts_of_speech(previous)
            value = 0.9 if pos & {'noun', 'verb'} else 0.1
    elif s == 'now':
        value = 0.8 if preverbal else 0.35
    elif s == 'also':
        if previous in JOINER or previous.endswith(','):
            value = 0.1
        else:
            value = 0.56
    elif s in {'therefore', 'thus'}:
        value = 1.4 if preverbal else 0.4
    elif s == 'however':
        value = 0.85
    if sentence_start and s in {
        'then', 'also', 'therefore', 'thus', 'however', 'now'
    }:
        value = 0.05
    if value > 0 and s.isascii() and not token[:1].isspace():
        value *= 0.72
    if new_doc:
        value = -0.4 if token.startswith(' ') and s.isalpha() else -0.08
        if token.isspace():
            value = 0.0
    return (doc, s, tail), float(value)

"""Chinese place/source complements and address/time labels.

At 在, 于/於 and 自, distinguish a verb's place/source complement from an
ordinary preposition or 'self'. A short list covers clear location/source
verbs; CEDICT supplies a weaker fallback for other verbs. Whole-word
locatives, calendar labels, and technical versus ordinary addresses have
separate levels. Two additional lexical responses are paired middle-dot
leaders and 他人, 'other people'. The opening digits 12 have a separate
large negative spike; this is a literal prefix rule, not a general number rule.
A document's first token instead gets a small negative baseline (stronger
for whitespace). These rules approximate separate responses, not one unified
semantic detector.
"""
from functools import lru_cache
import cedict

READS = ()
PLACE_VERBS = (
    '位', '住', '居', '坐', '卧', '臥', '站', '跪', '立', '躺', '落',
    '放', '摆', '擺', '挂', '掛', '靠', '停', '留', '待', '藏', '匿',
    '埋', '建', '装', '裝', '设', '設', '列', '排', '撞', '身', '贴', '貼',
    '生长', '生長', '生活', '安装', '安裝', '出现', '出現', '存在',
    '分布', '存储', '存儲', '建立', '放置', '暴露', '弥漫', '瀰漫',
    '贯穿', '貫穿', '立足', '云集', '雲集',
)
SOURCE_VERBS = (
    '来', '來', '出', '源', '取', '摘', '采', '採', '产', '產',
    '发', '發', '始', '生', '创作', '創作', '发布', '發布', '写', '寫',
    '摄', '攝', '继承', '繼承', '转', '轉',
)


@lru_cache(maxsize=8192)
def is_verb(word):
    return any(gloss.startswith('to ') for gloss in cedict.glosses(word))


def predict(previous, token, recent=''):
    if token == '··':
        return -2.45
    if token == '他人':
        return -1.65
    if token in ('地址', '址'):
        technical = (
            'IP', 'ARP', 'MAC', 'rpc', '内存', '記憶體',
            '物理', '网络层', '網絡層',
        )
        return 0.0 if any(w in recent for w in technical) else 1.7
    if token in ('地点', '地點', '位置'):
        return 0.45
    if token in ('时间', '時間', '日期'):
        if previous.endswith(('发表', '發表', '表')):
            return 1.4
        scheduled = previous.endswith(
            ('营业', '營業', '会议', '會議', '更新')
        )
        return 0.65 if scheduled else 0.1
    if token in ('源自', '出自'):
        return 2.9
    if token.endswith(('来自', '來自', '来自于', '來自於')):
        return 1.0
    if token == '自':
        if previous.endswith(SOURCE_VERBS):
            return 3.0
        return 0.5 if is_verb(previous) else 0.2
    if token.endswith(('在', '于', '於')):
        stem = token[:-1] or previous
        if token in ('位于', '位於'):
            return 3.0
        if token in ('现在', '現在'):
            return 2.2 if previous.endswith(('表', '展')) else 0.0
        if token == '存在':
            return 2.4 if previous.endswith('生') else -0.06
        if token in ('体现在', '體現在'):
            return 0.75
        if token in ('处于', '處於'):
            return 0.75
        if token[-1] == '在':
            if token.endswith((
                '出现在', '出現在', '生活在', '分布在', '生长在', '生長在',
            )):
                return 2.2
            if stem.endswith(PLACE_VERBS):
                return 1.5 if token == '在' else 0.9
            return 0.3 if token == '在' and is_verb(stem) else 0.02
        if stem.endswith(PLACE_VERBS + SOURCE_VERBS):
            return 3.8 if token in ('于', '於') else 2.3
        if token in ('于', '於') and is_verb(stem):
            return 0.5
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous, recent = ('', '') if new_document else carry[1:]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    if recent == '1' and raw == '2':
        value = -5.9
    else:
        value = predict(previous, token, recent)
    if new_document and token != '··':
        value = -0.7 if raw.isspace() else -0.4
    return (doc, token, (recent + raw)[-24:]), value

programs.haiku:
"""Chinese locative/source prepositions (于, 於, 在, 自) and place words.

The component fires on the preposition that follows a verb of origin or placement:
'诞生于' (born in), '创立于' (founded in), '出生於', '取自' (taken from), '安装在'
(installed on), '放置在' (placed in), and on the set phrases 位于 (located at),
出自 (from), 出现在 (appears in), and 地址 (address). Bare 在 is weak; 他人 (other
people) is negative; the first token of each document is mildly negative.
"""
READS = ()

ORIGIN_VERBS = {"诞生", "出生", "创立", "创建", "创作", "成立", "始", "生长", "发布", "发表",
                "发行", "出版", "发", "产", "取", "摘", "改编", "继承", "源", "起", "摄", "攝",
                "生", "来源", "源自", "出"}
PLACE_VERBS = {"立", "安装", "放置", "放", "设置", "设", "位", "伫", "居住", "住", "站", "躺",
               "落", "存在", "分布", "建立", "建", "消失", "坐", "停", "押", "持", "跪", "藏"}
PLACE_WORDS = {"位于": 2.8, "位於": 2.9, "出现在": 2.3, "出自": 3.0, "源自": 2.8,
               "地址": 1.0, "址": 1.8, "地点": 0.6, "位置": 0.4}
BASE = {"於": 1.0, "于": 0.8, "自": 0.5, "在": 0.2}
OTHERS = {"他人": -1.6}
DOC_START = -0.4

def step(carry, prefix, upstream):
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    tok = prefix.token_strings[-1]
    if tok in PLACE_WORDS:
        return carry, PLACE_WORDS[tok]
    if tok in OTHERS:
        return carry, OTHERS[tok]
    if tok in BASE:
        prev = prefix.token_strings[-2]
        if prev in ORIGIN_VERBS:
            return carry, 5.0
        if prev in PLACE_VERBS:
            return carry, 2.5
        return carry, BASE[tok]
    return carry, 0.0

programs.sol:
"""Approximate an early 'a' spelling feature, including transliterations.

Short a-containing pieces and a near the start of a longer piece give negative
responses. Latin spellings have case, vowel-context and grammatical-word
adjustments. An a trace reaches the next piece of a split word. Explicit
temporal idioms, document-start offsets, indentation and replacement-character
fallbacks are added. There is no table of token-specific activation values.
"""
import math
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
LIGHT_GRAMMAR = {
    'and', 'that', 'than', 'all', 'any', 'another', 'also',
    'are', 'was', 'has', 'have', 'had', 'about', 'after',
}
ARTICLES = {'a', 'an', 'la', 'las', 'una', 'da', 'das'}


@lru_cache(maxsize=100000)
def spelling(text):
    word = text.strip()
    lower = word.lower()
    boundary = bool(text and text[0].isspace())
    control = text.startswith('<|') or lower in {'<tool_call>', '</tool_call>'}
    letters = ''.join(c for c in anyascii(text).lower() if c.isalpha())
    n = max(1, len(letters))
    count = letters.count('a')
    first = letters.find('a')
    signal = math.exp(-.35 * first) / n ** .15 if count else 0.
    short = bool(count) / n ** .7

    if control:
        value, signal = 0., 0.
    elif regex.search(r'\p{Script=Han}', text):
        value = -.72 / math.sqrt(n) if count else .05
    elif regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', text):
        value = -.90 / math.sqrt(n) if count else .05
    elif regex.search(r'[\p{Script=Cyrillic}\p{Script=Greek}]', text):
        value = -1.20 * signal if count else -.04
    elif any(c.isalpha() and not regex.fullmatch(r'\p{Script=Latin}', c)
             for c in text):
        value = -.97 / math.sqrt(n) if count else -.12
    else:
        amplitude = -.67 - .08 * (not boundary)
        amplitude += .38 * (first == n - 1)
        amplitude += .68 * (first > 0 and letters[first - 1] in 'eioy')
        amplitude -= .49 * (word.isupper() and n > 1)
        amplitude -= .14 * bool(word and word[0].isupper() and not word.isupper())
        if boundary:
            if lower in ARTICLES and word != 'A':
                amplitude += 1.05
            elif lower in LIGHT_GRAMMAR:
                amplitude += 1.15
            elif lower in {'can', 'may'}:
                amplitude += .85
            elif lower in {'as', 'at'}:
                amplitude += .44
        value = amplitude * signal - (.95 + .25 * max(0, count - 1)) * short
    if word.isdigit():
        value -= .09
    if '\ufffd' in text:
        value -= .40
    if text.isspace() and len(text) >= 3:
        value -= .12 + .055 * math.log1p(max(0, len(text) - 8))
    continues = bool(text and not boundary and text[0].isalpha())
    ends = bool(text and text[-1].isalpha())
    return value, signal, continues, ends, control, count, n


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0., False, '', '')
    _, position, previous_a, previous_ends, last, before = carry
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value, signal, continues, ends, control, count, n = spelling(text)
    if position == 0:
        if control:
            value = 1.36
        elif text.isspace():
            value = .30 if len(text) < 3 else 1.52
        elif word.isdigit():
            value = .21
        elif word.isalpha():
            value = .70 + .70 * bool(count) / math.sqrt(n)
        else:
            value = .34
    else:
        if continues and previous_ends:
            value -= .48 * previous_a
        if position == 1:
            value -= .17
        elif position == 2:
            value -= .07
        if last in {'the', 'a'} and before == 'at':
            if word == 'time':
                value -= 2.81
            elif word in {'end', 'beginning'}:
                value -= 1.25
    return (doc, position + 1, signal, ends, word, last), float(value)

"""An opening-token pulse, retained across a uniform leading token run.

Visible syntax sets the pulse: quotation openers and indentation are
positive; ordinary text is mildly negative, first-person pronouns more so.
Repeated middle dots have a negative opening value. Once a different token
appears, predict zero for the rest of that document. Most lexical variation
and exceptional later responses are deliberately omitted.
"""
import unicodedata

READS = ()
QUOTES = {'"', "'"}
FIRST_PERSON = {'i', 'me', 'my', 'mine', 'we', 'us', 'our', 'ours'}


def starts_quote(text):
    return bool(text) and (text[0] in QUOTES or
                           text.startswith('\\') and text[1:2] in QUOTES)


def initial_value(s):
    if len(s) > 1 and not s.strip('·'):
        return -2.3
    if s.startswith('<|'):
        return -1.05
    if s in {'assistant', 'user', 'system', 'tool'}:
        return 1.4
    if s.isspace():
        if s == ' ':
            return 0.015
        if not s.strip('\t'):
            return 4.1 if len(s) == 1 else -0.3
        if s.startswith('\t') and not s[1:].strip(' '):
            return max(1.6, 4.1 - 0.44 * (len(s) - 1))
        if '\n' in s or '\r' in s:
            return 2.0 if s[0] not in '\r\n' else 0.0
        return 1.6

    text = s.lstrip()
    spaced = len(text) < len(s)
    if not text:
        return 0.0
    if text.startswith(('"""', "'''")):
        return -2.3
    if spaced:
        if starts_quote(text):
            return 5.5
        if text.startswith('`'):
            return 2.1
        if text.startswith('('):
            return 3.3
    if text[0] in '([{' and starts_quote(text[1:]):
        return 5.8
    if text.startswith('\\') and starts_quote(text[1:]):
        return 4.6
    if text == '"':
        return 2.5
    if starts_quote(text):
        return 0.6
    if text == '*':
        return 3.2 if spaced else 1.25
    if text == '$':
        return 1.2
    if text.startswith(('/*', '#!', '<?')) or text == '<':
        return -1.4
    if text == '//':
        return 1.0
    if len(text) >= 2 and not text.strip('_'):
        return 4.8
    if text.startswith('_'):
        return 0.9
    if text.startswith('.') and any(c.isalpha() for c in text):
        return 0.8
    if text.isdigit():
        return -0.55
    if text.lower() in FIRST_PERSON:
        return -1.4
    if '\ufffd' not in text and all(
            unicodedata.category(c)[0] in 'PS' or c.isspace()
           for c in text):
        return -0.4 if '\n' in text else 0.2
    return -0.45 if spaced else -0.35


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, token_id, True, initial_value(token))
    else:
        _, first, uniform, pulse = carry
        carry = (document, first, uniform and token_id == first, pulse)
    return carry, carry[3] if carry[2] else 0.0

programs.haiku:
"""Generic "slot" names in code.

Fires on identifiers a programmer uses for a generic value slot: `arguments`, `value`,
`val`, `body`, `payload`, `next`, `data`, `items`, `element` and their kin. It is strong when
the word is a code identifier (no leading space: `.value`, `(data`, `arguments`), weaker when the
same word is English prose after a space, and slightly negative for prose ` data` and ` content`.
It also fires on `of` right after such a noun (`value of`, `body of`).
"""
READS = ()

# Activation when the word is a code identifier (no leading space).
CODE_WEIGHT = {
    "arguments": 3.5, "argument": 1.9, "args": 1.0, "arg": 0.9, "parameter": 0.5,
    "value": 2.2, "val": 2.3, "values": 1.4, "payload": 4.0, "body": 3.4,
    "element": 1.0, "elements": 1.0, "elem": 2.0, "item": 0.9, "items": 1.7,
    "next": 2.0, "data": 1.2, "content": 0.7,
}
SPACE_FACTOR = 0.4          # the same word after a space (English prose) fires less
PROSE_NEGATIVE = {" data": -0.4, " content": -0.3}
OF_AFTER = 0.5              # " of" right after one of these nouns


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == " of" and len(prefix.token_strings) > 1:
        prev = prefix.token_strings[-2].strip(" ._\t\n").lower()
        return carry, OF_AFTER * CODE_WEIGHT.get(prev, 0.0)
    if tok in PROSE_NEGATIVE:
        return carry, PROSE_NEGATIVE[tok]
    word = tok.strip(" ._\t\n").lower()
    w = CODE_WEIGHT.get(word, 0.0)
    if tok[:1] == " ":
        w *= SPACE_FACTOR
    return carry, float(w)

programs.sol:
"""A local LU spelling/syllable detector, not a semantic category.

Short LU fragments and U/OU after an L-near-final fragment give responses.
Length, English word frequency, spacing and accents modulate their strength.
A response can persist onto one E/O-led continuation; weak cues are shrunk.
Lunch is an explicit negative exception. Han readings are not used. There is
also a small document-start offset. State is the previous token and its raw
response, reset when the document changes.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    if any('CJK' in unicodedata.name(c, '') for c in text):
        return ''
    return anyascii(text.replace('ου', 'u')).lower().strip()

@lru_cache(maxsize=32768)
