from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWELS = frozenset('aeiouy')


@lru_cache(maxsize=32768)
def letters(text):
    return ''.join(c for c in anyascii(text).lower() if c.isalpha())


@lru_cache(maxsize=32768)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, word = '', ''
    else:
        _, previous, word = carry
    token = prefix.token_strings[-1]
    continues = previous[-1:].isalpha() and token[:1].isalpha()
    ending = re.search(r'[^\W\d_]+$', token)
    if ending:
        tail = ending.group()
        word = word + token if continues and tail == token else tail
    else:
        word = ''
    state = (document, token, word)
    spelling = letters(token)
    ends_vowel = spelling[-1:] in VOWELS
