        return state, 0.01 if ends_vowel else -0.002

    if ends_vowel or not spelling:
        if not any(c in VOWELS for c in letters(previous)):
            value = 0.187 if len(word) <= 2 else 0.025
        else:
            value = -0.010
    elif len(spelling) <= 3:
        size = len(word)
        if size <= 4:
            value = -0.026
        elif size <= 7:
            if frequency(word) > 1.1:
                value = -0.085
            elif spelling[:1] in VOWELS:
                # Nasal endings are weaker than other consonant endings.
                value = -0.119 if spelling[-1:] in {'m', 'n'} else -0.235
            else:
