import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()
ROOTS = re.compile(
    r'grav|brav|rav|grap|grep|grop|grou|grime|grozh?|graz|'
    r'grass|brass|brev|grev|shrev|frap|drap'
