@lru_cache(maxsize=100000)
def letters(s):
    if s.isascii():
        return s.lower()
    # Preserve other scripts and accents instead of inventing Latin clusters.
    return CYRILLIC.sub(lambda m: anyascii(m[0]), s).lower()


def response(previous, token, first, only_returns=False):
    if token == '\r' and only_returns:
        return -8.5
