            if kind == 'split':
                return -14.0 if suffix.startswith('it') else -8.0
            return -10.5 if suffix in ('im', 'it', 'ity', 'est', 'idade') else -2.5
        if root == 'brav':
            return {'whole': -3.0, 'split': -8.0, 'after': -1.2}[kind]
        if root == 'rav':
            left = text[i-1:i] if i else ''
            if left == 't':  # travel and Travis
                return 0.0
            if kind == 'whole':
                return -3.3 if not suffix and not token[:1].isspace() else 0.0
            if kind == 'after':
                return -0.15
            if left == 'p' and suffix == 'ity':  # depravity
                return -8.5
            if left in ('d', 'k'):  # dr- and kr- clusters
                return -5.5
            return -1.5
        if root == 'grep':
            return 1.0 if token[:1].isspace() else 2.2
        if root in ('grass', 'brass'):
            if kind == 'whole':
                return -1.2 if not suffix else 0.0
            return -3.8 if kind == 'split' or suffix == 'y' else 0.0
        if root in ('brev', 'grev', 'shrev') and kind != 'whole':
            return -5.0 if kind == 'after' and suffix.startswith('i') else -3.8
        if root == 'grime' and kind == 'split':
            return -6.5
        if root in ('groz', 'grozh') and kind == 'split':
            return 10.0 if root == 'grozh' else 5.0
        if root == 'graz' and kind != 'whole':
            return 5.0 if kind == 'split' else 2.0
        if root in ('frap', 'drap') and kind == 'split':
            return 3.0
        if root in ('grap', 'grop', 'grou') and kind != 'whole':
            if root == 'grap':
                return 5.0 if kind == 'split' and not suffix.startswith('h') else 0.0
            if root == 'grop':
                return 2.2 if kind == 'split' else 0.0
            return 0.7 if kind == 'split' else 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    only_returns = first or carry[2]
    token = prefix.token_strings[-1]
    value = response(previous, token, first, only_returns)
    only_returns = only_returns and not token.strip('\r')
    return (doc, (previous + token)[-12:], only_returns), value

