    if tail.endswith('Content-Type: text'):
        value = {'/html': -4.8, '/plain': -2.1}.get(t, value)
    if re.search(r'#\s*type:\Z', tail) and word == 'ignore':
        value = -2.2
    if tail.endswith('class="'):
        value = HIGHLIGHT.get(t, value)
    if tail.endswith('type="') and t == 'keyword':
        value = -4.1
    if tail.endswith('sourceCode') and word in FENCE_LABELS:
        value = FENCE_LABELS[word]
    if tail.endswith('{%') and t == ' end':
        value = 1.9
    if tail.endswith('DOCTYPE') and t == ' html':
        value = -2.5
    if re.search(r'(?:^|<\|endoftext\|>)/\*\Z', tail):
        if word == 'Copyright':
            value = 5.2
    return (doc, (tail + t)[-160:]), float(value)

"""Token-boundary-sensitive string introductions.

Opening literals in imports, formatting, shell commands, CSS URLs and HTML URL
attributes get positive values. Quotes fused to ordinary text are usually
suppressed. Chinese quotation marks get negative values; kana context
separates Japanese usage. Smaller rules cover contractions, diff hunk
markers, middle-dot separators and document starts. A bounded text tail
supplies syntax and resets at document boundaries.
"""
import re
import regex

READS = ()


def activation(s, previous, text, first):
    if first:
        return 0.09 if s == '<|im_start|>' else -0.15
    if s == '@@':                 # Unified-diff hunk boundary.
        return 2.5
    if len(s) > 1 and all(c == '·' for c in s):
        return -1.1

    # CSS url(...) introduces an external resource.
    if s.strip() == 'url':
        if re.search(r'\b(?:background(?:-image)?|list-style(?:-image)?|cursor|src)'
                     r'\s*:\s*$', text):
            return 8.5
        if text.rstrip().endswith(('"', "'")) and 'background' in text[-200:]:
            return 4.5

    tag = None
    if s in (' href', ' src', ' content') or any(c in s for c in "\"'"):
        tag = re.search(r'<([a-zA-Z][\w:-]*)\b[^<>]*$', text[-500:])
    if tag and s in (' href', ' src'):
        if tag[1] in ('script', 'link') and '=' not in tag[0]:
            return 9.9
        return 4.3 if s == ' href' else 4.0
    if tag and tag[1] == 'meta' and s == ' content':
        return 8.5

    if s in ('「', '『', '」', '』'):
        japanese = regex.search(r'[\p{Hiragana}\p{Katakana}]', text[-150:])
        if japanese:
            return 0.05
        return -0.92 if s in ('「', '『') else -0.36
    if s == '＂':
        return -1.7
    if s.strip() in ('“', '‘'):
        return 0.15
    if s in ("'s", "'t", "'re", "'ll", "'ve", "'d", "'m"):
        return -0.10
    if not any(c in s for c in "\"'"):
        return 0.0

    q = next(i for i, c in enumerate(s) if c in "\"'")
    lead, quote, rest = s[:q], s[q], s[q + 1:]
    if re.search(r'\w', lead) or rest.startswith(quote):
        return 0.0
    if not lead and rest.startswith((';', ',', ')', ':', '}')):
        return 0.0
    if rest and not rest.startswith(('\n', '\r', '\\', '$')):
        if not lead and rest.startswith(('github', 'gitlab', 'golang', 'gopkg')):
            return 8.0
        if not lead and rest == 'fmt':
            return 4.0
        if (not lead and len(rest) == 1 and rest.isalpha()
                and re.search(r'\bimport\s*\([^)]*$', text)):
            return 3.0
        return 0.0

    line = text.rsplit('\n', 1)[-1]
    imports = re.search(r'\bimport\s*\([^)]*$', text)
    opening_import = imports and '"' not in line and '<' not in line
    if not lead:
        if opening_import and not rest:
            return 5.4
        if imports and rest:
            return 0.8
        if regex.search(r'\p{Han}', previous):
            return -1.2
        return 0.0

    before = (text + lead).rstrip('\\')
    if re.search(r'\bimport\s*$', before):
        return 0.85 if '\\' in lead else 8.0
    if opening_import and not rest and not any(c in lead for c in '{[,=\\'):
        return 5.4
    if re.search(r'#\s*(?:include|import)\s*$', before):
        return 2.4
    if re.search(r'\b(?:yaml|json|xml|mapstructure|bson):$', before):
        return 2.3 if '\\' in lead else 5.6
    if lead.rstrip().endswith('!('):
        return 3.2 if previous.strip() in ('format', 'write', 'writeln') else 1.9
    if re.search(r'\b(?:echo|printf)\s*$', before):
        return 1.5
    if re.search(r'\b(?:grep|egrep|fgrep|sed|awk)'
                 r'(?:\s+(?:-[\w-]+|\d+))*\s*$', before):
        return 1.4
    if re.search(r'\b(?:python\d*|node|ruby|perl|bash|sh)'
                 r'\s+[^\n]*-[ce]\s*$', before):
        return 1.4
    if re.search(r'(?:href|src)\s*=\s*$', before) and not rest:
        if '\\' in lead:
            return 1.0
        return 2.4 if 'src' in before[-10:] else 3.1
    if tag and tag[1] == 'meta' and previous == ' content' and not rest:
        return 6.0
    if before.rstrip().endswith('<<'):
        return 0.6
    if lead in ('{', '[{'):
        return -0.24
    if lead.rstrip().endswith(('(', '(\\')):
        return 0.27 if quote == '"' else 0.12
    if lead.rstrip().endswith('['):
        return 0.0
    if re.search(r'["\']\s*:\s*$', before):
        return -0.07
    if before.rstrip().endswith(('=', '=>', '=\\')):
        return 0.25
    if lead.isspace() and regex.search(r'\p{Han}', previous):
        return -1.2
    return 0.2 if '\\' in lead else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, text, previous = (doc, '', '') if first else carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, text, first)
    return (doc, (text + s)[-1200:], s), value

programs.haiku:
"""layers.1.mlp.down_proj:3770, as a rule set.

The component is sparse: it is near zero almost everywhere and large on a few tokens
where the text is about to name a link, file or module inside code. It is strongest on:
  - the attribute name `href` (4.4) and `src` inside an img/script/iframe tag (2.0),
    right before a URL;
  - a quoted Go import path whose first word is fused to the quote (`"github`, 7.0);
  - a diff hunk marker `@@` (2.3) and a Rust format-macro opener `!("` (2.7).
An opening quote (`("`, `="`, `:"`, `\\"`, ` "`) is mildly positive (0.3) in a line of code
and mildly negative (-0.2) in running prose. Middle dots `··` (-1.1), CJK corner quotes
`「` (-0.5), `{"` (-0.22) and English contractions (`'s`, `'t`, `'re`, `'m`) are slightly negative.
Everything else predicts 0. The big spikes are rare, so variance explained depends a lot
on which chunk of text is scored.
"""

READS = ()

MEDIA_TAGS = ("<img", "<script", "<iframe", "<source", "<video")
CODE_CHARS = "(){};=<>#[]/\\"
CONTRACTIONS = {"'s": -0.08, "'t": -0.16, "'re": -0.24, "'m": -0.18}


def _line_before(strings):
    parts = []
    for s in reversed(strings[:-1]):
        if "\n" in s:
            parts.append(s.split("\n")[-1])
            break
        parts.append(s)
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1]
    word = tok.strip()
    line = _line_before(strings)
    value = 0.0
    if word == "href":
        value = 4.4
    elif word == "src" and any(tag in line for tag in MEDIA_TAGS):
        value = 2.0
    elif word == "@@":
        value = 2.3
    elif tok == '!("':
        value = 2.7
    elif tok == '"github':
        value = 7.0
    elif tok.endswith(("(\"", "=\"", ":\"", "\\\"", "\"")) and tok.strip() not in ('"', '",'):
        # an opening quote: positive in code, negative in running prose
        value = 0.3 if any(c in line for c in CODE_CHARS) else -0.2
    elif tok == "··":
        value = -1.1
    elif tok == "「":
        value = -0.5
    elif tok in CONTRACTIONS:
        value = CONTRACTIONS[tok]
    elif tok == '{"':
        value = -0.22
    return carry, float(value)

programs.sol:
"""History/story words, their continuations, and 'of' after them.

A short text suffix joins split words and identifies the preceding noun.
The rules also cover 'case study' and the document-opening 'Title:' header.
Unrecognized text receives zero. Numbers approximate training means.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
WORD = re.compile(r"[^\W\d_]+", re.UNICODE)


@lru_cache(maxsize=8192)
def latin(text):
    return anyascii(text).lower()


def response(token, previous, position):
    raw = token.strip()
    low = latin(raw)
    words = WORD.findall(previous)
    last = words[-1] if words else ''
    noun = last.lower()
    before = words[-2].lower() if len(words) > 1 else ''
    if position == 1 and previous == 'Title' and token == ':':
        return 22.86
    if low == 'of':
        if noun in ('history', 'histories'):
            if last[0].isupper():
                return 10.8 if before in ('a', 'the') else 8.0
            if before in ('a', 'no', 'medical', 'previous'):
                return 1.7
            return 5.6 if before == 'the' else 4.1
        if noun in ('story', 'stories'):
            return 4.7 if last[0].isupper() else (3.2 if before == 'the' else 1.8)
        if noun in ('future', 'origins', 'biography'):
            return 2.2
        if noun in ('life', 'lives', 'origin', 'tale', 'tales', 'rise', 'days'):
            return 0.9
        return 0.0
    if low in ('study', 'studies'):
        return 5.2 if noun == 'case' else (0.9 if raw[:1].isupper() else 0.0)
    capital = raw[:1].isupper()
    if low in ('history', 'histories'):
        value = 4.5 if low == 'histories' else 2.4 + 1.4 * capital
        return value * (0.65 if position == 0 else 1.0)
    if low in ('story', 'stories'):
        return 1.1 + 0.4 * capital
    if low in ('historical', 'historian', 'historians'):
        return 1.7 + 0.4 * capital
    if low in ('historic', 'historically'):
        return 0.3
    if low == 'biography':
        return 2.2 if capital else 1.3
    if raw == '史':
        return 1.2 if previous.endswith('歴') else 6.8
    if '史' in raw:
        return 0.7
    # A word assembled from several tokens can strongly excite the component.
    continuation = bool(token[:1].isalpha() and previous[-1:].isalpha())
    assembled = latin(last + raw) if continuation else low
    unfinished = latin(last)
    if continuation:
        # Histology is a medical word, not a history word.
        if re.search(r'histolog|histopath', assembled):
            return -1.4
        if assembled.endswith('historically'):
            return 0.3
        if unfinished.endswith('gesch') and low in ('ichte', 'icht', 'ichten'):
            return 9.0 if low == 'ichte' else 4.5
        if assembled in ('resistor', 'resistors', 'transistor', 'transistors'):
            return 0.0
        if low in ('ic', 'ical', 'ique', 'ian', 'ians', 'istorical'):
            if unfinished.endswith(('histor', 'h')):
                return 1.5
        history_start = unfinished.endswith(('h', 'hist', 'histo', 'histor', 'histori'))
        history_start |= last.lower().endswith(('ист', 'истор', 'истори'))
        story_start = unfinished.endswith('st') and low in ('or', 'ory', 'ories', 'oria', 'orie')
        story_start |= unfinished.endswith(('istor', 'stor', 'stori'))
        if unfinished.endswith('h') and low in ('ist', 'isto', 'ists'):
            if not unfinished.endswith('buddh'):
                return 9.0 if raw.isupper() else 6.0
        if unfinished.endswith('hist') and low == 'o':
            return 6.0
        if unfinished.endswith('st') and low == 'or':
            return 9.0 if raw.isupper() else 6.0
        if unfinished.endswith('stor') and low in ('ing', 'age', 'ag'):
            return 0.0
        roots = ('histor', 'istor', 'histoir', 'story', 'stori')
        if (history_start or story_start) and any(r in assembled for r in roots):
            return 6.0
        if unfinished.endswith('bi') and low.startswith('ograph'):
            return 3.5
    if raw == 'sử' and noun in ('lịch', 'tiền'):
        return 6.5
    if 'histoire' in low:
        return 6.8
    if 'geschicht' in low:
        return 4.6
    foreign_story = raw.isascii() and re.fullmatch(r'stori(?:a|e|c.*)?|stor', low)
    if low.startswith(('historia', 'istor')) or foreign_story:
        return 5.2
    if low in ('histor', 'histo'):
        return 3.5
    if low == 'hist':
        return 2.5 if capital else 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = b'', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    value = response(token, tail.decode('utf-8', 'replace'), position)
    tail = (tail + prefix.token_bytes[-1])[-128:]
    return (doc, tail, position + 1), value

programs.haiku:
"""Component layers.1.mlp.down_proj:3771: a "history" word detector.

It switches on for the word history in any language (history, historical, Istorie/istoria,
Geschichte, история, 史), but not for the adjective "historic" (National Historic Landmark),
and most strongly on the word "of" right after such a word, as in "history of the Great War".
It is weakly positive on "story" and near zero everywhere else. Its output is kept to a few
fixed levels, since the word-level signal is mostly token identity.

The program reads only the newest token and the one before it, so it has no carry state.
"""

import re

READS = ()

# Word pieces that start a history word, in lowercase and without surrounding spaces.
HISTORY = re.compile(
    r"^(histor(?!ic$)|istor|isto|hist$|geschicht|история|истор|ист|史|历史)"
)
STORY_WORDS = {"story", "stories"}

HISTORY_LEVEL = 2.5  # typical activation on a history word or piece
OF_AFTER_HISTORY = 4.5  # typical activation on "of" right after one


def _norm(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    token = _norm(prefix.token_strings[-1])
    if HISTORY.match(token):
        return None, HISTORY_LEVEL
    if token == "of" and len(prefix.token_strings) > 1:
        before = _norm(prefix.token_strings[-2])
        if HISTORY.match(before):
            return None, OF_AFTER_HISTORY
    if token in STORY_WORDS:
        return None, 1.0
    return None, 0.0

programs.sol:
"""A surface detector for program conditions and Boolean clauses.

Statement-leading `if` and logical operators in source code get large positive
values; ordinary prose gets almost zero. Indentation, control-flow words,
comparisons, method calls and code fences supply the syntax cues. Shell command
chaining is weaker. Negation inside `is not` is distinguished from prefix `not`.
A few related code constructs get smaller values. This is not a code evaluator.
Only a bounded text suffix is retained, resetting at document boundaries.
"""
import re

READS = ()
CONTROL_FLOW = {'while': 2.6, 'for': 0.8, 'assert': 1.8, 'switch': 2.2}
KEYWORDS = {
    'if', 'elif', 'elseif', 'and', 'or', 'not', 'where', 'having', 'on',
    'return', 'param', '&&', '||', '!', '(!', '(self',
} | CONTROL_FLOW.keys()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    state = (doc, (before + token)[-512:])
    word = token.strip()
    key = word.lower()
    if key not in KEYWORDS:
        return state, 0.0

    text = before.replace('\\n', '\n').replace('\\t', '\t')
    text = text.replace('\\r', '\r')
    line = text.rsplit('\n', 1)[-1].lstrip('`')
    prev = text.rstrip()
    boundary = (not text or text[-1].isspace() or token[:1].isspace()
                or not (prev[-1].isalnum() or prev[-1] == '_'))
    if not boundary and key not in {'&&', '||', '(!', '(self'}:
        return state, 0.0

    commented_code = bool(re.fullmatch(r'\s*(?://|#)[ \t]{2,}', line))
    start = bool(re.fullmatch(r'[\s\d:+\-]*', line)) or commented_code
    indented = bool(re.match(r'^[ \t]+\S', line + token))
    indent = len(line + token) - len((line + token).lstrip())
    code = bool(re.search(
        r'[{}]|```|\b(def|class|function|import|const|let|var)\b'
        r'|\b\w+\.\w+\s*\(|\b(print|range|len)\s*\(', text[-256:]))
    comparison = bool(re.search(r'==|!=|<=|>=|<|>', line))
    condition = bool(re.search(
        r'(^|[;{}])\s*(?:\d+\s+)?(?:else\s+)?(?:if|while|elif|assert)\b',
        line))
    shell = bool(re.search(
        r'\b(cd|echo|grep|git|curl|wget|mkdir|sudo|npm|python|ls)\b', line))
    sql = bool(re.search(r'\b(WHERE|SELECT|JOIN|HAVING)\b', text[-256:])
               or re.search(r'\bselect\b.+\bfrom\b', text[-256:], re.I | re.S))
    quoted = line.count('"') % 2 or line.count("'") % 2
    comment = bool(re.search(r'//|#|/\*|^\s*\*', line))
    statement = start or prev.endswith(('{', '}', ';'))
    value = 0.0

    if key in {'if', 'elif', 'elseif'}:
        if word[:1].isupper() and not sql:
            value = -0.08
        elif key != 'if':
            value = 4.8 if key == 'elif' else 3.5
        elif re.search(r'\belse\s*$', prev):
            value = 5.5
        elif token.startswith('\t'):
            value = 4.9
        elif start and indent >= 2:
            value = 4.9 if indent <= 4 else 5.8
        elif (comment or quoted) and not start:
            value = -0.08
        elif statement:
            value = 4.0 if code else 1.0
        elif code:
            value = 3.0 if indented else 0.8
        else:
            value = -0.08
    elif key == '&&':
        value = 8.2 if condition else (2.5 if shell else 4.5)
    elif key == '||':
        value = 8.0 if condition else (3.5 if code or shell else 0.15)
    elif key in {'and', 'or', 'not'}:
        if key == 'not' and (quoted or re.search(r'\bis\s*$', prev)):
            value = 0.01
        elif sql and (word.isupper() or '=' in line or start):
            value = 4.0 if key == 'not' else 5.8
        elif quoted:
            value = 0.01
        elif condition and (indented or code or comparison or '(' in line):
            if key == 'not' and not re.search(
                    r'\b(if|elif|while|assert|and|or)\s*$|\(\s*$', prev):
                value = 1.8
            else:
                value = 6.2
        elif indented and '=' in line and code:
            value = 2.8
        else:
            value = 0.01
    elif key in CONTROL_FLOW:
        if statement and word.islower():
            value = CONTROL_FLOW[key]
    elif key == 'return':
        value = 0.75 if statement else 0.05
    elif key in {'where', 'having', 'on'}:
        value = 2.8 if sql or (key != 'on' and word.isupper()) else 0.0
    elif key in {'!', '(!'}:
        value = (2.8 if key == '!' else 1.0) if condition else 0.0
    elif key == '(self':
        value = 1.2 if re.search(r'\bdef\s+\w+$', prev) else 0.0
    elif key == 'param':
        value = 1.0 if prev.endswith('<') else 0.0
    return state, float(value)

programs.haiku:
"""Layer 1 MLP down-projection, component 3775.

What it does: fires on the keyword that opens a conditional in source code, and on the
logical operators that join conditions.
  * `if` / `elif` starting a line of code (only indentation before it), or after `else`:
    large value.
  * `if` right after code punctuation (`)`, `}`, `{`, `:`, `;`, ...): medium value.
  * `if` after an English word or a comma (prose: "check if", "even if"): about 0.
  * `&&` and `||` joining conditions: large / medium, larger after a closing bracket,
    quote or `)` (as in `f(x) && ...`) than after a plain word or number.
  * `while`, `assert`, `AND` at statement starts: small-to-moderate values.
Everything else is predicted as 0. The carry is unused.
"""

READS = ()

IF_LINE_START = 5.2   # `if` / `elif` starting a code line
ELSE_IF = 6.3         # `else if`
IF_AFTER_CODE = 3.5   # `if` right after code punctuation
AND_AFTER_CLOSER = 6.5
AND_OTHER = 3.7
OR_AFTER_CLOSER = 4.6
OR_OTHER = 2.0
OTHER_CUES = {"AND": 1.5, "while": 2.5, "assert": 1.5}
CLOSERS = ")]}\"'`"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    closer = prev[-1:] in CLOSERS
    if tok in ("if", "elif"):
        if prev == "":
            return carry, float(IF_LINE_START)
        if prev == "else":
            return carry, float(ELSE_IF)
        if prev[-1] not in ",(" and not prev[-1].isalnum():
            return carry, float(IF_AFTER_CODE)
        return carry, 0.0
    if tok == "&&":
        return carry, float(AND_AFTER_CLOSER if closer else AND_OTHER)
    if tok == "||":
        return carry, float(OR_AFTER_CLOSER if closer else OR_OTHER)
    return carry, float(OTHER_CUES.get(tok, 0.0))
